# Dans reasoning.py, perception.py, etc.

def _apply_llm_inference(self, task: ReasoningTask, result: ReasoningResult) -> bool:
    """
    Utilisation du module LLM dans le raisonnement.
    """
    llm_engine = self.nexus_core.get_module("llm_engine")
    if not llm_engine:
        result.logs.append("LLM engine not available")
        return False

    # Création d'une requête LLM
    request = LLMRequest(
        prompt=prompt_templates.chain_of_thought_prompt(task.goal, task.context),
        temperature=0.3,  # plus déterministe pour le raisonnement
        request_type="completion"
    )

    try:
        # Exécution de la requête
        response = llm_engine.complete(request)

        # Parsing de la réponse
        parsed = llm_engine.parse_response(response, "chain_of_thought")

        # Utilisation des résultats
        if parsed.get("conclusion"):
            result.conclusions.append(parsed["conclusion"])
            result.intermediate_steps.extend(parsed.get("steps", []))
            result.confidence = parsed.get("confidence", 0.5)
            return True

        return False
    except Exception as e:
        result.logs.append(f"LLM inference error: {e}")
        return False

