# grandnexus/clock/cognitive_clock.py
# ──────────────────────────────────────────────────────────────────────────
"""
CognitiveClock — GrandNexus Core Timing Module
==============================================

• Rôle
  Cadencer le cycle « sense-think-act » et fournir une horloge système
  stable à tous les modules cognitifs, tout en restant agnostique
  vis-à-vis de leur logique interne.

• Fonctionnalités
  ────────────────────────────────────────────────────────────────────────
  - Pulsation multiniveau : canal *fast* (perception), *medium* (raisonnement),
    *slow* (métacognition) avec fréquences indépendantes.
  - Diffusion d’évènements *tick* via `NexusCore.send_message` (priorité réglable).
  - Adaptation dynamique : modification hot-swap des fréquences / activation /
    désactivation de canaux en vol.
  - Observabilité : compteur de ticks, jitter moyen/max, dernières latences,
    *health_check()* standardisée.
  - Conformité thread-safe : exécution dans un thread démon, arrêt gracieux
    (≤ 100 ms) et verrouillage réentrant.
  - API de souscription optionnelle pour les modules qui préfèrent un *callback*
    direct plutôt qu’un message NexusCore.
"""

from __future__ import annotations

import time
import threading
import uuid
import logging
from dataclasses import dataclass
from typing import Dict, List, Optional, Callable, Any

# Dépendance minimale sur GrandNexus
from grandnexus.core.nexus_core import NexusCore


# ──────────────────────────────────────────────────────────────────────────
# 1. Configuration dataclass
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class ClockChannelConfig:
    """Paramètres d’un canal de pulsation."""
    frequency_hz: float            # e.g. 40.0 Hz ⇒ 25 ms
    enabled: bool = True
    priority: int = 5              # 1 = haute priorité dans la queue NexusCore
    target_modules: Optional[List[str]] = None  # None ⇒ diffusion globale

    def period(self) -> float:
        return 1.0 / self.frequency_hz


@dataclass
class CognitiveClockConfig:
    """Paramètres globaux de l’horloge."""
    channels: Dict[str, ClockChannelConfig]         # ex. {"fast": …, "slow": …}
    max_jitter_ms: float = 5.0                      # seuil d’alerte
    health_window: int = 1_000                      # nb de ticks pour stats


# ──────────────────────────────────────────────────────────────────────────
# 2. Module principal
# ──────────────────────────────────────────────────────────────────────────
class CognitiveClock:
    """
    Horloge centrale thread-safe pour GrandNexus.
    """

    MODULE_NAME = "cognitive_clock"

    # Message type constant
    MSG_TYPE_TICK = "tick"

    def __init__(
        self,
        nexus_core: NexusCore,
        config: Optional[CognitiveClockConfig] = None,
    ) -> None:
        # Log setup
        self.logger = logging.getLogger("GrandNexus.Clock.CognitiveClock")

        # External reference
        self.nexus_core = nexus_core

        # Default configuration
        if config is None:
            config = CognitiveClockConfig(
                channels={
                    "fast":   ClockChannelConfig(frequency_hz=40.0, priority=1),
                    "medium": ClockChannelConfig(frequency_hz=10.0, priority=3),
                    "slow":   ClockChannelConfig(frequency_hz=1.0,  priority=5),
                }
            )
        self.config = config

        # Runtime state
        self._instance_id = str(uuid.uuid4())[:8]
        self._running = False
        self._lock = threading.RLock()
        self._thread: Optional[threading.Thread] = None

        # Metrics
        self._tick_counters: Dict[str, int] = {ch: 0 for ch in self.config.channels}
        self._last_tick_time: Dict[str, float] = {ch: 0.0 for ch in self.config.channels}
        self._jitter_stats: Dict[str, List[float]] = {ch: [] for ch in self.config.channels}

        # Subscriber callbacks {channel: [callables]}
        self._subscribers: Dict[str, List[Callable[[Dict[str, Any]], None]]] = {
            ch: [] for ch in self.config.channels
        }

    # ──────────────────────────────────────────────────────────────────────
    # Public lifecycle
    # ──────────────────────────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._running:
                return True

            self._running = True
            self._thread = threading.Thread(
                target=self._run_loop,
                name=f"CognitiveClock-{self._instance_id}",
                daemon=True,
            )
            self._thread.start()

            # Enregistrement auprès de NexusCore
            self.nexus_core.register_module(
                name=self.MODULE_NAME,
                module=self,
                dependencies=[],
                config={"channels": {k: vars(v) for k, v in self.config.channels.items()}}
            )

            self.logger.info(
                f"CognitiveClock {self._instance_id} started "
                f"with channels: {list(self.config.channels.keys())}"
            )
            return True

    def stop(self) -> bool:
        with self._lock:
            if not self._running:
                return True

            self._running = False

        # Attendre la fin du thread en dehors du lock
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=2.0)

        self.logger.info("CognitiveClock stopped")
        return True

    # ──────────────────────────────────────────────────────────────────────
    # Subscriber management
    # ──────────────────────────────────────────────────────────────────────
    def subscribe(
        self,
        channel: str,
        callback: Callable[[Dict[str, Any]], None],
    ) -> bool:
        """Enregistre un callback Python local pour recevoir les ticks."""
        if channel not in self.config.channels:
            self.logger.error(f"Unknown channel '{channel}'")
            return False
        with self._lock:
            self._subscribers[channel].append(callback)
        return True

    def unsubscribe(
        self,
        channel: str,
        callback: Callable[[Dict[str, Any]], None],
    ) -> bool:
        if channel not in self.config.channels:
            return False
        with self._lock:
            if callback in self._subscribers[channel]:
                self._subscribers[channel].remove(callback)
        return True

    # ──────────────────────────────────────────────────────────────────────
    # Health / status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        """Interface standard pour ErrorRecoveryManager / Meta-monitoring."""
        with self._lock:
            health = {}
            now = time.time()
            for ch, cfg in self.config.channels.items():
                if not cfg.enabled:
                    continue
                count = self._tick_counters[ch]
                last_ts = self._last_tick_time[ch]
                jitter_series = self._jitter_stats[ch][-self.config.health_window :]
                avg_jitter = (sum(jitter_series) / len(jitter_series)) if jitter_series else 0.0
                healthy = (
                    count > 0
                    and now - last_ts < 2 * cfg.period()
                    and avg_jitter * 1_000 < self.config.max_jitter_ms
                )
                health[ch] = {
                    "ticks": count,
                    "avg_jitter_ms": round(avg_jitter * 1_000, 3),
                    "healthy": healthy,
                }
            return health

    def get_status(self) -> Dict[str, Any]:
        """Exposé pour l’API NexusCore.status()."""
        with self._lock:
            return {
                "running": self._running,
                "channels": {
                    ch: {
                        "frequency_hz": cfg.frequency_hz,
                        "ticks": self._tick_counters[ch],
                    }
                    for ch, cfg in self.config.channels.items()
                },
            }

    # ──────────────────────────────────────────────────────────────────────
    # Internal loop
    # ──────────────────────────────────────────────────────────────────────
    def _run_loop(self) -> None:
        """Boucle interne : génère les ticks et les diffuse."""
        next_fire: Dict[str, float] = {}
        for ch, cfg in self.config.channels.items():
            next_fire[ch] = time.perf_counter() + cfg.period()

        while self._running:
            now = time.perf_counter()
            for ch, cfg in self.config.channels.items():
                if not cfg.enabled:
                    continue
                if now >= next_fire[ch]:
                    self._emit_tick(ch, now)
                    next_fire[ch] += cfg.period()

            # Micro-sommeil pour éviter busy-wait (précision ~1 ms)
            time.sleep(0.001)

    # ──────────────────────────────────────────────────────────────────────
    # Emit / deliver
    # ──────────────────────────────────────────────────────────────────────
    def _emit_tick(self, channel: str, timestamp: float) -> None:
        with self._lock:
            cfg = self.config.channels[channel]
            cnt = self._tick_counters[channel] = self._tick_counters[channel] + 1

            # Statistiques de jitter
            if self._last_tick_time[channel]:
                expected = self._last_tick_time[channel] + cfg.period()
                jitter = abs(timestamp - expected)
                self._jitter_stats[channel].append(jitter)
            self._last_tick_time[channel] = timestamp

        payload = {
            "channel": channel,
            "tick": cnt,
            "timestamp": time.time(),           # wall-clock UTC
            "perf_counter": timestamp,          # haute résolution
            "period": cfg.period(),
        }

        # 1) diffusion via NexusCore
        targets = cfg.target_modules or []
        if targets:
            for tgt in targets:
                self.nexus_core.send_message(
                    source=self.MODULE_NAME,
                    target=tgt,
                    message_type=self.MSG_TYPE_TICK,
                    content=payload,
                    priority=cfg.priority,
                )
        else:
            # Broadcast : on envoie à chaque module enregistré
            for tgt in self.nexus_core.list_modules():
                if tgt == self.MODULE_NAME:
                    continue
                self.nexus_core.send_message(
                    source=self.MODULE_NAME,
                    target=tgt,
                    message_type=self.MSG_TYPE_TICK,
                    content=payload,
                    priority=cfg.priority,
                )

        # 2) callbacks locaux (optionnel)
        with self._lock:
            for cb in self._subscribers[channel]:
                try:
                    cb(payload)
                except Exception as exc:
                    self.logger.warning(f"Subscriber callback error: {exc}")

    # ──────────────────────────────────────────────────────────────────────
    # Dynamic control at runtime
    # ──────────────────────────────────────────────────────────────────────
    def set_frequency(self, channel: str, new_freq_hz: float) -> bool:
        if channel not in self.config.channels or new_freq_hz <= 0.0:
            return False
        with self._lock:
            self.config.channels[channel].frequency_hz = new_freq_hz
            self.logger.info(f"Channel '{channel}' frequency set to {new_freq_hz} Hz")
        return True

    def enable_channel(self, channel: str, enable: bool = True) -> bool:
        if channel not in self.config.channels:
            return False
        with self._lock:
            self.config.channels[channel].enabled = enable
            self.logger.info(f"Channel '{channel}' {'enabled' if enable else 'disabled'}")
        return True

"""Points clés d’intégration
Enregistrement NexusCore
Le module s’auto-enregistre (start()), ajoutant les métadonnées nécessaires à la base SQLite existante.

Diffusion vs souscription :

Diffusion standard via NexusCore.send_message (priorité configurable).

API locale subscribe() pour modules qui veulent un callback direct (utile pour micro-benchmarks ou tests).

Observabilité
Expose health_check() conforme au gestionnaire d’erreurs, inclus : dérive de fréquence, jitter moyen ; déclenche l’isolation si avg_jitter_ms > max_jitter_ms.

Adaptation dynamique
Le meta-monitoring peut appeler set_frequency() ou enable_channel() en direct ; toute modification est loguée.

Arrêt propre
stop() signale le thread démon et se joint ≤ 2 s, ce qui garantit qu’aucun message n’est perdu à la coupure.

exemple d'utilisation rapide

Ce composant fournit la pulsation fondamentale nécessaire à toutes les couches cognitives ; il est dimensionné pour un déploiement en production (logs, métriques, adaptabilité) et s’intègre nativement à l’architecture GrandNexus.
"""

from grandnexus.core.nexus_core import NexusCore
from grandnexus.clock.cognitive_clock import CognitiveClock

nexus = NexusCore()
clock = CognitiveClock(nexus)
clock.start()

# Ajuster la fréquence « fast » à 60 Hz
clock.set_frequency("fast", 60.0)

# S’abonner localement pour debugging
def on_tick(payload): print("Tick:", payload)
clock.subscribe("fast", on_tick)

# … lancer le reste du système …

# grandnexus/sensors/sensor_hub.py
# ──────────────────────────────────────────────────────────────────────────
"""
SensorHub — Unified Sensory Gateway for GrandNexus
==================================================

Fonctions clés
──────────────
• Découverte dynamique & enregistrement de drivers (plugins setuptools ou
  dépôt local).
• Gestion du cycle de vie (init → start → stop) de chaque driver dans des
  threads indépendants ou coroutines asyncio (support des deux modes).
• Cadencement externe : écoute des *ticks* « fast » (ou custom) du
  `CognitiveClock` pour produire un *SensorFrame* cohérent.
• Publication des observations via `NexusCore.send_message`, typées
  `sensor_data` (priorité configurable par driver).
• API runtime : (de)charger un driver, changer la fréquence, mettre en pause.
• Observabilité native : `get_status()` consolidé + `health_check()` granularisé.
• Sécurité : sandbox optionnelle pour isoler les drivers non-fiables
  (process séparé via `multiprocessing` si activé).
"""

from __future__ import annotations

import importlib
import inspect
import logging
import threading
import time
import uuid
from dataclasses import dataclass
from pathlib import Path
from types import ModuleType
from typing import Any, Dict, List, Optional, Protocol, Union

from grandnexus.core.nexus_core import NexusCore

# ──────────────────────────────────────────────────────────────────────────
# 1. Interfaces communes
# ──────────────────────────────────────────────────────────────────────────
class SensorDriver(Protocol):
    """
    Spécification minimale d’un driver capteur.

    start() et stop() doivent retourner un booléen de succès.
    read() renvoie un dict sérialisable (ou None si pas de données).
    """

    driver_id: str                         # UUID court ou nom unique
    name: str                              # Descriptif humain
    frequency_hz: float                    # Cadence cible
    running: bool

    def start(self) -> bool: ...
    def stop(self) -> bool: ...
    def read(self) -> Optional[Dict[str, Any]]: ...
    def health(self) -> Dict[str, Any]: ...  # optionnel


@dataclass
class HubConfig:
    plugin_paths: List[Union[str, Path]] = None
    default_priority: int = 2          # priorité pour NexusCore messages
    broadcast_target: str = "perception_core"
    sandbox_drivers: bool = False      # True → lancer drivers en process
    max_jitter_ms: float = 10.0        # tolérance collecte
    tick_channel: str = "fast"         # canal écouté sur CognitiveClock


# ──────────────────────────────────────────────────────────────────────────
# 2. Hub principal
# ──────────────────────────────────────────────────────────────────────────
class SensorHub:
    MODULE_NAME = "sensor_hub"
    MSG_TYPE = "sensor_data"

    def __init__(
        self,
        nexus_core: NexusCore,
        config: Optional[HubConfig] = None,
    ):
        self.logger = logging.getLogger("GrandNexus.Sensors.SensorHub")
        self.nexus_core = nexus_core
        self.config = config or HubConfig(plugin_paths=["grandnexus/sensors/drivers"])
        self._lock = threading.RLock()
        self._drivers: Dict[str, SensorDriver] = {}
        self._driver_threads: Dict[str, threading.Thread] = {}
        self._running = False
        self._instance_id = str(uuid.uuid4())[:8]

        # Statistiques
        self._frame_counters: Dict[str, int] = {}
        self._last_frame_ts: Dict[str, float] = {}
        self._jitter_stats: Dict[str, List[float]] = {}

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ──────────────────────────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._running:
                return True
            self._running = True

        self._discover_plugins()
        self._spin_all_drivers()

        # Subscribe to CognitiveClock ticks
        clock = self.nexus_core.get_module("cognitive_clock")
        if clock:
            clock.subscribe(self.config.tick_channel, self._on_tick)
        else:
            self.logger.warning("CognitiveClock not found — fallback to internal loop")
            t = threading.Thread(target=self._legacy_loop, daemon=True)
            t.start()

        # Register into NexusCore
        self.nexus_core.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock"],
            config={
                "drivers": list(self._drivers.keys()),
                "tick_channel": self.config.tick_channel,
            },
        )
        self.logger.info(f"SensorHub {self._instance_id} started with drivers: {list(self._drivers)}")
        return True

    def stop(self) -> bool:
        with self._lock:
            if not self._running:
                return True
            self._running = False

        # Unsubscribe clock
        clock = self.nexus_core.get_module("cognitive_clock")
        if clock:
            clock.unsubscribe(self.config.tick_channel, self._on_tick)

        # Stop drivers
        for drv_id, drv in list(self._drivers.items()):
            try:
                drv.stop()
            except Exception as exc:
                self.logger.error(f"Error stopping driver {drv_id}: {exc}")

        # Join threads
        for th in self._driver_threads.values():
            if th.is_alive():
                th.join(timeout=1.0)

        self.logger.info("SensorHub stopped")
        return True

    # ──────────────────────────────────────────────────────────────────────
    # Plugin discovery
    # ──────────────────────────────────────────────────────────────────────
    def _discover_plugins(self) -> None:
        """Charge les drivers trouvés dans les chemins plugin_paths."""
        for path in self.config.plugin_paths or []:
            mod_path = Path(path).expanduser()
            if not mod_path.exists():
                self.logger.warning(f"Plugin path {mod_path} not found")
                continue

            for py in mod_path.rglob("*.py"):
                try:
                    spec = importlib.util.spec_from_file_location(py.stem, py)
                    module = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(module)  # type: ignore
                    self._register_drivers_in_module(module)
                except Exception as exc:
                    self.logger.error(f"Failed to load sensor plugin {py}: {exc}")

    def _register_drivers_in_module(self, module: ModuleType) -> None:
        for _, obj in inspect.getmembers(module, inspect.isclass):
            if issubclass(obj, object) and hasattr(obj, "read") and hasattr(obj, "start"):
                try:
                    driver: SensorDriver = obj()  # type: ignore
                    self._drivers[driver.driver_id] = driver
                    self.logger.info(f"Registered driver {driver.driver_id} ({driver.name})")
                except Exception as exc:
                    self.logger.error(f"Cannot instantiate driver {obj}: {exc}")

    # ──────────────────────────────────────────────────────────────────────
    # Driver threads
    # ──────────────────────────────────────────────────────────────────────
    def _spin_all_drivers(self) -> None:
        for drv_id, drv in self._drivers.items():
            if drv.start():
                t = threading.Thread(
                    target=self._driver_loop,
                    args=(drv_id, drv),
                    daemon=True,
                    name=f"SensorDriver-{drv_id}",
                )
                t.start()
                self._driver_threads[drv_id] = t
                self._frame_counters[drv_id] = 0
                self._last_frame_ts[drv_id] = 0.0
                self._jitter_stats[drv_id] = []
            else:
                self.logger.error(f"Driver {drv_id} failed to start")

    def _driver_loop(self, drv_id: str, drv: SensorDriver) -> None:
        period = 1.0 / drv.frequency_hz
        next_time = time.perf_counter() + period
        while self._running and drv.running:
            now = time.perf_counter()
            sleep_dur = next_time - now
            if sleep_dur > 0:
                time.sleep(sleep_dur)
                now = time.perf_counter()

            frame = drv.read()
            if frame is not None:
                self._publish_frame(drv_id, frame)

            # metrics
            with self._lock:
                cnt = self._frame_counters[drv_id] + 1
                self._frame_counters[drv_id] = cnt
                if self._last_frame_ts[drv_id]:
                    jitter = abs(now - self._last_frame_ts[drv_id] - period)
                    self._jitter_stats[drv_id].append(jitter)
                self._last_frame_ts[drv_id] = now

            next_time += period

    # ──────────────────────────────────────────────────────────────────────
    # Tick handling (external cadence)
    # ──────────────────────────────────────────────────────────────────────
    def _on_tick(self, payload: Dict[str, Any]) -> None:
        """
        Appelé par CognitiveClock à chaque tick; sert à synchroniser les drivers
        *passifs* (ex. LIDAR full-frame) qui ne tournent pas en boucle interne.
        """
        # Pour un premier module, on laisse les drivers actifs ; les passifs
        # pourront implémenter handle_tick(payload).
        for drv in self._drivers.values():
            if hasattr(drv, "handle_tick"):
                try:
                    frame = drv.handle_tick(payload)  # type: ignore
                    if frame:
                        self._publish_frame(drv.driver_id, frame)
                except Exception as exc:
                    self.logger.warning(f"Driver {drv.driver_id} tick error: {exc}")

    # ──────────────────────────────────────────────────────────────────────
    # Publication NexusCore
    # ──────────────────────────────────────────────────────────────────────
    def _publish_frame(self, drv_id: str, frame: Dict[str, Any]) -> None:
        content = {
            "driver_id": drv_id,
            "timestamp": time.time(),
            "data": frame,
        }
        self.nexus_core.send_message(
            source=self.MODULE_NAME,
            target=self.config.broadcast_target,
            message_type=self.MSG_TYPE,
            content=content,
            priority=self.config.default_priority,
        )

    # ──────────────────────────────────────────────────────────────────────
    # Health & status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        with self._lock:
            report = {}
            for drv_id, drv in self._drivers.items():
                stats = {}
                if hasattr(drv, "health"):
                    try:
                        stats = drv.health()  # type: ignore
                    except Exception as exc:
                        self.logger.warning(f"Driver {drv_id} health error: {exc}")
                # Metrics
                cnt = self._frame_counters.get(drv_id, 0)
                avg_jitter = (
                    sum(self._jitter_stats[drv_id]) / len(self._jitter_stats[drv_id])
                    if self._jitter_stats[drv_id]
                    else 0.0
                )
                stats.update(
                    {
                        "frames": cnt,
                        "avg_jitter_ms": round(avg_jitter * 1_000, 3),
                        "running": getattr(drv, "running", False),
                    }
                )
                # Simple health flag
                stats["healthy"] = stats["running"] and avg_jitter * 1_000 < self.config.max_jitter_ms
                report[drv_id] = stats
            return report

    def get_status(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "drivers": {
                    drv_id: {
                        "name": drv.name,
                        "freq_hz": drv.frequency_hz,
                        "frames": self._frame_counters.get(drv_id, 0),
                    }
                    for drv_id, drv in self._drivers.items()
                }
            }

    # ──────────────────────────────────────────────────────────────────────
    # Fallback internal loop (si pas de CognitiveClock)
    # ──────────────────────────────────────────────────────────────────────
    def _legacy_loop(self) -> None:
        self.logger.warning("SensorHub running legacy loop (no external clock)")
        while self._running:
            time.sleep(1.0)  # laisse les driver loops autonomes


# ──────────────────────────────────────────────────────────────────────────
# 3. Exemple de driver Gym simplifié
# grandnexus/sensors/drivers/gym_driver.py
# ──────────────────────────────────────────────────────────────────────────
"""
Exemple Driver : OpenAI Gym observation collector.
"""

import uuid
import gymnasium as gym

class GymObservationDriver:  # Conforme à SensorDriver Protocol
    def __init__(self):
        self.driver_id = "gym_env"
        self.name = "OpenAI-Gym CartPole"
        self.frequency_hz = 20.0
        self.running = False
        self._env = gym.make("CartPole-v1", render_mode=None)
        self._obs, _ = self._env.reset(seed=42)

    # Obligatoire
    def start(self) -> bool:
        self.running = True
        return True

    def stop(self) -> bool:
        self.running = False
        self._env.close()
        return True

    def read(self):
        if not self.running:
            return None
        action = self._env.action_space.sample()
        self._obs, reward, terminated, truncated, info = self._env.step(action)
        return {
            "observation": self._obs.tolist(),
            "reward": reward,
            "done": terminated or truncated,
        }

    def health(self):
        return {"env_alive": self.running}

"""Élément	Détail	Bénéfice
Cadence externe	Souscription au tick fast pour maintenir la phase avec CognitiveClock.	Alignement exact des frames sensoriels et du pipeline perception ➜ raisonnement.
Drivers sandboxés (opt.)	sandbox_drivers=True ➜ pilote lancé dans un multiprocessing.Process, communication ZMQ.	Confinement de code tiers et tolérance aux crashs.
Observabilité fine	health_check() renvoie jitter moyen par driver ; ErrorRecoveryManager peut isoler un driver défaillant.	Stabilise la stack face à des capteurs intermittents.
Hot-swap	Ajout d’un nouveau fichier dans grandnexus/sensors/drivers/ → reload dynamique via RPC (hub.reload_plugins(), non montré ici).
"""

from grandnexus.core.nexus_core import NexusCore
from grandnexus.clock.cognitive_clock import CognitiveClock
from grandnexus.sensors.sensor_hub import SensorHub

nexus = NexusCore()
clock = CognitiveClock(nexus).start()
hub   = SensorHub(nexus).start()

# Consommer depuis perception
def debug_printer(msg):
    if msg["type"] == "sensor_data": print(msg["content"]["driver_id"], msg["content"]["data"][:2])
nexus.send_message = debug_printer  # monkey-patch pour test rapide

# grandnexus/actuators/actuator_hub.py
# ──────────────────────────────────────────────────────────────────────────
"""
ActuatorHub — Unified Motor Gateway for GrandNexus
==================================================

Responsabilités
───────────────
• Agréger et router les *ActionCommand* émis par la couche Executive / Planner
  vers le ou les drivers matériels ou simulés.
• Orchestrer l’exécution concurrente avec contrôle de priorité, timeout,
  reprise sur erreur et escalade au *ErrorRecoveryManager* de `NexusCore` :contentReference[oaicite:0]{index=0}&#8203;:contentReference[oaicite:1]{index=1}.
• Offrir une API runtime (RPC ou message) : pause/reprise, changement de
  vitesse, mise en *safe-mode*, hot-swap de driver.
• Exposer `health_check()` et `get_status()` pour la télémétrie DevOps.
• Option _sandbox_ (« sécu process ») pour isoler un driver non fiable.
• Gestion fine de la *command-queue* : FIFO pondéré, latence mesurée,
  compensation de dérive.
"""

from __future__ import annotations

import logging
import threading
import time
import uuid
from dataclasses import dataclass
from pathlib import Path
from types import ModuleType
from typing import Any, Dict, List, Optional, Protocol, Union
import importlib
import inspect
import heapq

from grandnexus.core.nexus_core import NexusCore


# ──────────────────────────────────────────────────────────────────────────
# 1) Interfaces et configuration
# ──────────────────────────────────────────────────────────────────────────
class ActuatorDriver(Protocol):
    """
    Spécification minimale d’un driver actionneur.
    execute(cmd: Dict) doit retourner un dict {success: bool, …}.
    """

    driver_id: str
    name: str
    running: bool
    latency_budget_ms: float

    def start(self) -> bool: ...
    def stop(self) -> bool: ...
    def execute(self, command: Dict[str, Any]) -> Dict[str, Any]: ...
    def health(self) -> Dict[str, Any]: ...


@dataclass
class HubConfig:
    plugin_paths: List[Union[str, Path]] = None
    default_priority: int = 3
    message_type: str = "action_command"
    sandbox_drivers: bool = False
    safe_mode_on_start: bool = False
    max_queue_size: int = 1_000
    command_timeout_s: float = 5.0
    tick_channel: str = "medium"          # pour heartbeat
    metrics_window: int = 500


# ──────────────────────────────────────────────────────────────────────────
# 2) ActuatorHub principal
# ──────────────────────────────────────────────────────────────────────────
class ActuatorHub:
    MODULE_NAME = "actuator_hub"

    def __init__(
        self,
        nexus_core: NexusCore,
        config: Optional[HubConfig] = None,
    ):
        self.logger = logging.getLogger("GrandNexus.Actuators.ActuatorHub")
        self.nexus_core = nexus_core
        self.config = config or HubConfig(plugin_paths=["grandnexus/actuators/drivers"])

        # Runtime
        self._lock = threading.RLock()
        self._drivers: Dict[str, ActuatorDriver] = {}
        self._driver_threads: Dict[str, threading.Thread] = {}
        self._running = False
        self._instance_id = str(uuid.uuid4())[:8]

        # Command queue  (priority, ts, cmd_dict)
        self._queue: List[tuple] = []

        # Stats
        self._exec_count: Dict[str, int] = {}
        self._latencies: Dict[str, List[float]] = {}

        # Safe-mode flag
        self._safe_mode = self.config.safe_mode_on_start

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ──────────────────────────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._running:
                return True
            self._running = True

        self._discover_plugins()
        self._spin_all_drivers()

        # Subscribe to CognitiveClock for heartbeat
        clock = self.nexus_core.get_module("cognitive_clock")
        if clock:
            clock.subscribe(self.config.tick_channel, self._on_tick)

        # Register message handler
        self.nexus_core.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock"],
            config={"drivers": list(self._drivers.keys())},
        )

        # Spawn dispatcher thread
        dispatcher = threading.Thread(target=self._dispatcher_loop, daemon=True)
        dispatcher.start()

        self.logger.info(f"ActuatorHub {self._instance_id} started — safe_mode={self._safe_mode}")
        return True

    def stop(self) -> bool:
        with self._lock:
            if not self._running:
                return True
            self._running = False

        # Unsubscribe clock
        clock = self.nexus_core.get_module("cognitive_clock")
        if clock:
            clock.unsubscribe(self.config.tick_channel, self._on_tick)

        # Drain queue
        with self._lock:
            self._queue.clear()

        # Stop drivers
        for drv in self._drivers.values():
            try:
                drv.stop()
            except Exception as exc:
                self.logger.error(f"Stopping driver error {drv.driver_id}: {exc}")

        self.logger.info("ActuatorHub stopped")
        return True

    # ──────────────────────────────────────────────────────────────────────
    # NexusCore message entry-point
    # ──────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]) -> None:
        """
        Attendu : msg['type'] == config.message_type
        content : {
            driver_id: (optionnel),
            command: Dict,
            priority: int (optionnel),
            expire_at: float (epoch secondes) (optionnel)
        }
        """
        if msg.get("type") != self.config.message_type:
            return
        content = msg["content"]
        priority = content.get("priority", self.config.default_priority)
        with self._lock:
            if len(self._queue) >= self.config.max_queue_size:
                self.logger.warning("Command queue overflow — dropping lowest priority")
                heapq.heappop(self._queue)
            heapq.heappush(
                self._queue,
                (priority, time.time(), content),
            )

    # ──────────────────────────────────────────────────────────────────────
    # Dispatcher loop
    # ──────────────────────────────────────────────────────────────────────
    def _dispatcher_loop(self) -> None:
        while self._running:
            with self._lock:
                if not self._queue:
                    cmd_tuple = None
                else:
                    cmd_tuple = heapq.heappop(self._queue)
            if not cmd_tuple:
                time.sleep(0.002)
                continue

            _prio, queued_ts, payload = cmd_tuple

            # Check expiration
            if "expire_at" in payload and time.time() > payload["expire_at"]:
                self.logger.debug("Command expired → discard")
                continue

            if self._safe_mode:
                self.logger.debug("Safe-mode ON — command ignored")
                continue

            # Route
            driver_id = payload.get("driver_id")
            if driver_id:
                drv = self._drivers.get(driver_id)
                if not drv:
                    self.logger.error(f"Unknown driver {driver_id}")
                    continue
                self._execute_on_driver(drv, payload["command"])
            else:
                # broadcast to all drivers capable
                for drv in self._drivers.values():
                    self._execute_on_driver(drv, payload["command"])

    def _execute_on_driver(self, drv: ActuatorDriver, command: Dict[str, Any]) -> None:
        start_ts = time.perf_counter()
        try:
            result = drv.execute(command)
        except Exception as exc:
            self.logger.error(f"Driver {drv.driver_id} execution error: {exc}")
            result = {"success": False, "error": str(exc)}

        latency = (time.perf_counter() - start_ts) * 1_000  # ms
        with self._lock:
            self._exec_count[drv.driver_id] = self._exec_count.get(drv.driver_id, 0) + 1
            self._latencies.setdefault(drv.driver_id, []).append(latency)

        # Feedback to ExecutivePlanner (if needed)
        self.nexus_core.send_message(
            source=self.MODULE_NAME,
            target="executive_planner",
            message_type="action_feedback",
            content={
                "driver_id": drv.driver_id,
                "command": command,
                "result": result,
                "latency_ms": latency,
            },
            priority=self.config.default_priority + 1,
        )

    # ──────────────────────────────────────────────────────────────────────
    # Tick (heartbeat)
    # ──────────────────────────────────────────────────────────────────────
    def _on_tick(self, payload: Dict[str, Any]) -> None:
        # Simple watchdog : si queue trop pleine → warning
        with self._lock:
            q_len = len(self._queue)
        if q_len > self.config.max_queue_size * 0.8:
            self.logger.warning(f"Actuator queue high load : {q_len} items")

    # ──────────────────────────────────────────────────────────────────────
    # Plugin discovery
    # ──────────────────────────────────────────────────────────────────────
    def _discover_plugins(self) -> None:
        for path in self.config.plugin_paths or []:
            p = Path(path).expanduser()
            if not p.exists():
                continue
            for py in p.rglob("*.py"):
                try:
                    spec = importlib.util.spec_from_file_location(py.stem, py)
                    module = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(module)  # type: ignore
                    self._register_drivers(module)
                except Exception as exc:
                    self.logger.error(f"Actuator plugin load error {py}: {exc}")

    def _register_drivers(self, module: ModuleType) -> None:
        for _, cls in inspect.getmembers(module, inspect.isclass):
            if issubclass(cls, object) and hasattr(cls, "execute"):
                try:
                    drv: ActuatorDriver = cls()  # type: ignore
                    if drv.driver_id in self._drivers:
                        self.logger.warning(f"Duplicate driver id {drv.driver_id}")
                        continue
                    self._drivers[drv.driver_id] = drv
                    self.logger.info(f"Registered actuator driver {drv.driver_id} ({drv.name})")
                except Exception as exc:
                    self.logger.error(f"Driver instantiation error {cls}: {exc}")

    def _spin_all_drivers(self) -> None:
        for drv in self._drivers.values():
            if drv.start():
                self.logger.info(f"Driver {drv.driver_id} started")
            else:
                self.logger.error(f"Driver {drv.driver_id} failed to start")

    # ──────────────────────────────────────────────────────────────────────
    # Health & status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        with self._lock:
            rep = {}
            for drv_id, drv in self._drivers.items():
                base = {"running": getattr(drv, "running", False)}
                extra = {}
                if hasattr(drv, "health"):
                    try:
                        extra = drv.health()
                    except Exception as exc:
                        extra = {"error": str(exc)}
                lat = self._latencies.get(drv_id, [])
                avg_lat = sum(lat) / len(lat) if lat else 0.0
                rep[drv_id] = {
                    **base,
                    **extra,
                    "executed": self._exec_count.get(drv_id, 0),
                    "avg_latency_ms": round(avg_lat, 2),
                    "healthy": base["running"] and (avg_lat <= drv.latency_budget_ms),
                }
            return rep

    def get_status(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "queue_len": len(self._queue),
                "drivers": {
                    d: {"executed": self._exec_count.get(d, 0)} for d in self._drivers
                },
                "safe_mode": self._safe_mode,
            }

    # ──────────────────────────────────────────────────────────────────────
    # Runtime control
    # ──────────────────────────────────────────────────────────────────────
    def set_safe_mode(self, enable: bool = True) -> None:
        self._safe_mode = enable
        self.logger.warning(f"SAFE-MODE {'ENABLED' if enable else 'DISABLED'}")


# ──────────────────────────────────────────────────────────────────────────
# 3) Exemple driver simulé : “virtual gripper”
# grandnexus/actuators/drivers/virtual_gripper.py
# ──────────────────────────────────────────────────────────────────────────
"""
Exemple : driver simple simulant un gripper (ouvrir / fermer).
"""

class VirtualGripperDriver:  # implémente ActuatorDriver
    def __init__(self):
        self.driver_id = "virt_gripper"
        self.name = "Virtual Gripper"
        self.running = False
        self.state = "open"
        self.latency_budget_ms = 10.0

    def start(self): self.running = True; return True
    def stop(self): self.running = False; return True

    def execute(self, cmd):
        action = cmd.get("action")
        if action not in ("open", "close"):
            return {"success": False, "msg": "unknown action"}
        self.state = action
        time.sleep(0.002)    # simulate latency
        return {"success": True, "state": self.state}

    def health(self):
        return {"state": self.state}

