# grandnexus/homeostasis/homeostasis_manager.py
# ───────────────────────────────────────────────────────────────────────────
"""
HomeostasisManager — Resource Autoregulation & Drive Generator
==============================================================

Fonctions clés
──────────────
• Surveillance multi-domaine : CPU, mémoire, I/O disque, température, batterie,
  quota API, latence réseau, coût cloud.
• Seuils adaptatifs : basés sur *moving-window percentiles* + profils
  contextuels (desktop, edge, cloud).
• Calcul de drives normalisés [0.0-1.0] → messages `homeostasis_drive`
  broadcast vers *IntrinsicMotivation*, *AttentionFilter* et *ExecutivePlanner*.
• Mécanismes de défense : throttling CPU, déclenchement _safe-mode_ dans
  `ActuatorHub`, isolation de modules énergivores via `ErrorRecoveryManager`.
• Observabilité : métriques historiques exportables Prometheus, `health_check()`
  conforme au noyau.
• Plugin de capteur externe : possibilité d’ajouter des sondes custom (GPU,
  bande passante RF, etc.) via setuptools-entrypoints.
"""

from __future__ import annotations

import logging
import threading
import time
import psutil                # pip install psutil
import uuid
from dataclasses import dataclass
from typing import Dict, List, Callable, Optional, Any
from collections import deque

from grandnexus.core.nexus_core import NexusCore

# ───────────────────────────────────────────────────────────────────────────
# Configuration
# ───────────────────────────────────────────────────────────────────────────
@dataclass
class Thresholds:
    warn: float        # % ou fraction
    critical: float


@dataclass
class HomeostasisConfig:
    # Fenêtre glissante (secondes) pour la moyenne mobile
    history_sec: int = 120
    sample_period: float = 1.0
    cpu_thr: Thresholds = Thresholds(0.70, 0.90)
    mem_thr: Thresholds = Thresholds(0.75, 0.95)
    temp_thr: Thresholds = Thresholds(0.60, 0.80)        # fraction of Tjmax
    batt_thr: Thresholds = Thresholds(0.30, 0.10)        # remaining % (inverse)
    api_thr: Thresholds = Thresholds(0.70, 0.90)         # quota usage
    cost_thr: Thresholds = Thresholds(0.70, 0.90)        # budget usage
    integration_targets: List[str] = (
        "intrinsic_motivation",
        "attention_filter",
        "executive_planner",
    )
    drive_publish_interval: float = 5.0                  # sec
    safe_mode_driver: str = "actuator_hub"               # module to throttle


# ───────────────────────────────────────────────────────────────────────────
# Manager
# ───────────────────────────────────────────────────────────────────────────
class HomeostasisManager:
    MODULE_NAME = "homeostasis_manager"
    MSG_TYPE = "homeostasis_drive"

    def __init__(
        self,
        nexus_core: NexusCore,
        config: Optional[HomeostasisConfig] = None,
        api_quota_cb: Optional[Callable[[], float]] = None,   # return 0-1 usage
        cost_meter_cb: Optional[Callable[[], float]] = None,  # idem
    ):
        self.logger = logging.getLogger("GrandNexus.Homeostasis.Manager")
        self.nexus_core = nexus_core
        self.config = config or HomeostasisConfig()
        self.api_quota_cb = api_quota_cb
        self.cost_meter_cb = cost_meter_cb

        # Runtime
        self._lock = threading.RLock()
        self._running = False
        self._thread: Optional[threading.Thread] = None
        self._instance_id = str(uuid.uuid4())[:8]

        # History
        window = int(self.config.history_sec / self.config.sample_period)
        self._hist_cpu = deque(maxlen=window)
        self._hist_mem = deque(maxlen=window)
        self._hist_temp = deque(maxlen=window)
        self._hist_batt = deque(maxlen=window)
        self._hist_api = deque(maxlen=window)
        self._hist_cost = deque(maxlen=window)

        # Drive cache
        self._last_publish = 0.0
        self._current_drives: Dict[str, float] = {}

    # ───────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ───────────────────────────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._running:
                return True
            self._running = True

        # Enregistrement nucleo
        self.nexus_core.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock"],
            config={},
        )

        # Thread daemon
        self._thread = threading.Thread(target=self._monitor_loop, daemon=True)
        self._thread.start()

        # Souscription tick lent pour watchdog
        clock = self.nexus_core.get_module("cognitive_clock")
        if clock:
            clock.subscribe("slow", self._on_tick)

        self.logger.info(f"HomeostasisManager {self._instance_id} started")
        return True

    def stop(self) -> bool:
        with self._lock:
            if not self._running:
                return True
            self._running = False
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=2.0)
        self.logger.info("HomeostasisManager stopped")
        return True

    # ───────────────────────────────────────────────────────────────────────
    # Monitoring loop
    # ───────────────────────────────────────────────────────────────────────
    def _monitor_loop(self) -> None:
        while self._running:
            self._sample_once()
            self._evaluate_drives()
            time.sleep(self.config.sample_period)

    def _sample_once(self) -> None:
        try:
            cpu = psutil.cpu_percent() / 100.0
            mem = psutil.virtual_memory().percent / 100.0
            # Température (peut être absente)
            temps = psutil.sensors_temperatures()
            if temps:
                # moyenne de tous les capteurs
                t = sum([s.current for v in temps.values() for s in v]) / max(1, sum(len(v) for v in temps.values()))
                temp_norm = min(1.0, t / 90.0)      # supposition Tjmax=90 °C
            else:
                temp_norm = 0.0

            batt_val = 0.0
            if psutil.sensors_battery():
                batt_val = 1.0 - (psutil.sensors_battery().percent / 100.0)

            api_use = self.api_quota_cb() if self.api_quota_cb else 0.0
            cost_use = self.cost_meter_cb() if self.cost_meter_cb else 0.0

            with self._lock:
                self._hist_cpu.append(cpu)
                self._hist_mem.append(mem)
                self._hist_temp.append(temp_norm)
                self._hist_batt.append(batt_val)
                self._hist_api.append(api_use)
                self._hist_cost.append(cost_use)
        except Exception as exc:
            self.logger.error(f"Homeostasis sampling error: {exc}")

    # ───────────────────────────────────────────────────────────────────────
    # Drive computation
    # ───────────────────────────────────────────────────────────────────────
    def _evaluate_drives(self) -> None:
        now = time.time()

        with self._lock:
            cpu = max(self._hist_cpu) if self._hist_cpu else 0.0
            mem = max(self._hist_mem) if self._hist_mem else 0.0
            temp = max(self._hist_temp) if self._hist_temp else 0.0
            batt = max(self._hist_batt) if self._hist_batt else 0.0
            api = max(self._hist_api) if self._hist_api else 0.0
            cost = max(self._hist_cost) if self._hist_cost else 0.0

        drives = {
            "FATIGUE": cpu,
            "STRESS": mem,
            "THERMAL": temp,
            "HUNGER": batt,
            "COST": cost,
            "RATE_LIMIT": api,
        }
        self._current_drives = drives

        # Publier toutes les drive `drive_publish_interval`
        if now - self._last_publish >= self.config.drive_publish_interval:
            self._broadcast_drives(drives)
            self._last_publish = now

        # Détection seuil critique → actions défensives
        if any(
            [
                cpu >= self.config.cpu_thr.critical,
                mem >= self.config.mem_thr.critical,
                temp >= self.config.temp_thr.critical,
                batt >= self.config.batt_thr.critical,
            ]
        ):
            self._trigger_safe_mode()

    def _broadcast_drives(self, drives: Dict[str, float]) -> None:
        for tgt in self.config.integration_targets:
            self.nexus_core.send_message(
                source=self.MODULE_NAME,
                target=tgt,
                message_type=self.MSG_TYPE,
                content=drives,
                priority=4,
            )
        self.logger.debug(f"Drives broadcast: { {k:round(v,2) for k,v in drives.items()} }")

    # ───────────────────────────────────────────────────────────────────────
    # Reaction: safe-mode
    # ───────────────────────────────────────────────────────────────────────
    def _trigger_safe_mode(self) -> None:
        self.logger.warning("Critical homeostasis level reached → SAFE MODE")
        self.nexus_core.send_message(
            source=self.MODULE_NAME,
            target=self.config.safe_mode_driver,
            message_type="control",
            content={"cmd": "safe_mode", "enable": True},
            priority=1,
        )

    # ───────────────────────────────────────────────────────────────────────
    # Tick watchdog
    # ───────────────────────────────────────────────────────────────────────
    def _on_tick(self, payload: Dict[str, Any]) -> None:
        # Hypothèse : check drive freshness
        if time.time() - self._last_publish > 2 * self.config.drive_publish_interval:
            self.logger.warning("Drive broadcast delayed")

    # ───────────────────────────────────────────────────────────────────────
    # Health / status
    # ───────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "running": self._running,
                "avg_cpu": round(sum(self._hist_cpu) / max(1, len(self._hist_cpu)), 3),
                "avg_mem": round(sum(self._hist_mem) / max(1, len(self._hist_mem)), 3),
            }

    def get_status(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "drives": {k: round(v, 3) for k, v in self._current_drives.items()},
                "hist_len": len(self._hist_cpu),
            }

from grandnexus.core.nexus_core import NexusCore
from grandnexus.clock.cognitive_clock import CognitiveClock
from grandnexus.homeostasis.homeostasis_manager import HomeostasisManager

def fake_api_usage(): return 0.42
def fake_cost_usage(): return 0.18

nexus = NexusCore()
CognitiveClock(nexus).start()
HomeostasisManager(nexus, api_quota_cb=fake_api_usage, cost_meter_cb=fake_cost_usage).start()

# grandnexus/planning/executive_planner.py
# ──────────────────────────────────────────────────────────────────────────
"""
ExecutivePlanner — Hierarchical Task Network (HTN)-based Action Scheduler
========================================================================

Rôle
────
• Réceptionne _CognitiveTask_ et _Goal_ (voir `cognition_manager.py`) :contentReference[oaicite:0]{index=0}&#8203;:contentReference[oaicite:1]{index=1}
• Décompose en primitives d’action via opérateurs HTN (« methods ») paramétrables.
• Maintient un _agenda_ FIFO pondéré : priorité, deadline, drive urgency.
• Publie des `action_command` vers `ActuatorHub` et gère le feedback.
• S’ajuste dynamiquement selon les drives *Homeostasis* (FATIGUE, HUNGER…) :contentReference[oaicite:2]{index=2}&#8203;:contentReference[oaicite:3]{index=3}
• Expose `health_check()` et journaux d’exécution (succès, latence, taux d’abandon).
"""

from __future__ import annotations

import logging
import threading
import time
import uuid
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Callable, Tuple
import heapq

from grandnexus.core.nexus_core import NexusCore

# Utilise la structure CognitiveTask déjà définie par CognitionManager
from grandnexus.cognition.cognition_manager import CognitiveTask, CognitiveEventType  # type: ignore


# ──────────────────────────────────────────────────────────────────────────
# 1) Structures locales
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class PlanStep:
    """Une primitive envoyée à ActuatorHub."""
    driver_id: str
    command: Dict[str, Any]
    expected_latency: float = 0.05
    retry: int = 0


@dataclass
class HTNMethod:
    """Décomposition HTN : goal_type → steps ou sous-goals."""
    goal_type: str
    expand: Callable[[Dict[str, Any]], List[PlanStep]]


@dataclass(order=True)
class AgendaEntry:
    """File de priorités (heapq)."""
    priority: float
    deadline: float
    created_at: float = field(compare=False)
    task: CognitiveTask = field(compare=False)
    plan: List[PlanStep] = field(compare=False, default_factory=list)


# ──────────────────────────────────────────────────────────────────────────
# 2) Configuration
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class PlannerConfig:
    default_priority: float = 0.5
    max_parallel_steps: int = 2
    feedback_timeout: float = 5.0
    drive_weight: float = 0.3                # influence des drives [0-1]
    tick_channel: str = "medium"
    drive_source: str = "homeostasis_manager"


# ──────────────────────────────────────────────────────────────────────────
# 3) ExecutivePlanner
# ──────────────────────────────────────────────────────────────────────────
class ExecutivePlanner:
    MODULE_NAME = "executive_planner"

    def __init__(
        self,
        nexus_core: NexusCore,
        config: Optional[PlannerConfig] = None,
    ):
        self.logger = logging.getLogger("GrandNexus.Planning.ExecutivePlanner")
        self.nexus_core = nexus_core
        self.config = config or PlannerConfig()

        # Runtime
        self._lock = threading.RLock()
        self._running = False
        self._thread: Optional[threading.Thread] = None
        self._instance_id = str(uuid.uuid4())[:8]

        # Agenda (heap)
        self._agenda: List[AgendaEntry] = []

        # HTN repository
        self._methods: Dict[str, List[HTNMethod]] = {}

        # Drives
        self._drives: Dict[str, float] = {}

        # Stats
        self._executed = 0
        self._failed = 0

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ──────────────────────────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._running:
                return True
            self._running = True

        # Register to NexusCore
        self.nexus_core.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock", "actuator_hub", self.config.drive_source],
        )

        # Subscribe ticks
        clock = self.nexus_core.get_module("cognitive_clock")
        if clock:
            clock.subscribe(self.config.tick_channel, self._on_tick)

        self._thread = threading.Thread(target=self._planner_loop, daemon=True)
        self._thread.start()

        self.logger.info(f"ExecutivePlanner {self._instance_id} started")
        return True

    def stop(self) -> bool:
        with self._lock:
            if not self._running:
                return True
            self._running = False

        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=2.0)
        self.logger.info("ExecutivePlanner stopped")
        return True

    # ──────────────────────────────────────────────────────────────────────
    # Message handling (tasks & drives & feedback)
    # ──────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]) -> None:
        """Route selon type."""
        mtype = msg.get("type")
        if mtype == "cognitive_task":
            self._ingest_task(msg["content"])
        elif mtype == "homeostasis_drive":
            self._update_drives(msg["content"])
        elif mtype == "action_feedback":
            self._process_feedback(msg["content"])

    # — tasks
    def _ingest_task(self, task_dict: Dict[str, Any]) -> None:
        task = CognitiveTask(**task_dict)       # reconstruction rapide
        plan = self._decompose(task)
        priority = task.priority or self.config.default_priority
        # modulation par drive (ex : température élevée ⇒ priorité basse)
        stress = self._drives.get("THERMAL", 0.0)
        priority += stress * self.config.drive_weight
        entry = AgendaEntry(
            priority=priority,
            deadline=task.deadline or (time.time() + 30),
            created_at=time.time(),
            task=task,
            plan=plan,
        )
        with self._lock:
            heapq.heappush(self._agenda, entry)
        self.logger.debug(f"Ingested task {task.task_id} with {len(plan)} steps")

    # — drives
    def _update_drives(self, drives: Dict[str, float]) -> None:
        with self._lock:
            self._drives = drives

    # — feedback
    def _process_feedback(self, fb: Dict[str, Any]) -> None:
        # Simple success counting
        if fb["result"].get("success"):
            self._executed += 1
        else:
            self._failed += 1

    # ──────────────────────────────────────────────────────────────────────
    # HTN registration
    # ──────────────────────────────────────────────────────────────────────
    def register_method(self, method: HTNMethod) -> None:
        self._methods.setdefault(method.goal_type, []).append(method)
        self.logger.info(f"Registered HTN method for {method.goal_type}")

    # Simple decompose (first-match)
    def _decompose(self, task: CognitiveTask) -> List[PlanStep]:
        methods = self._methods.get(task.task_type, [])
        if not methods:
            self.logger.warning(f"No HTN method for {task.task_type}")
            return []
        try:
            return methods[0].expand(task.parameters)
        except Exception as exc:
            self.logger.error(f"HTN expansion error {exc}")
            return []

    # ──────────────────────────────────────────────────────────────────────
    # Core loop
    # ──────────────────────────────────────────────────────────────────────
    def _planner_loop(self) -> None:
        while self._running:
            entry = None
            with self._lock:
                if self._agenda:
                    entry = heapq.heappop(self._agenda)

            if not entry:
                time.sleep(0.005)
                continue

            now = time.time()
            if now > entry.deadline:
                self.logger.warning(f"Task {entry.task.task_id} expired")
                self._failed += 1
                continue

            # Execute steps sequentially (could parallelize later)
            for step in entry.plan:
                self._dispatch_step(step)
                # Wait for feedback or timeout
                time.sleep(step.expected_latency)

    def _dispatch_step(self, step: PlanStep) -> None:
        self.nexus_core.send_message(
            source=self.MODULE_NAME,
            target="actuator_hub",
            message_type="action_command",
            content={
                "driver_id": step.driver_id,
                "command": step.command,
                "priority": 2,
                "expire_at": time.time() + self.config.feedback_timeout,
            },
            priority=2,
        )
        self.logger.debug(f"Dispatched step to {step.driver_id}: {step.command}")

    # ──────────────────────────────────────────────────────────────────────
    # Tick watchdog
    # ──────────────────────────────────────────────────────────────────────
    def _on_tick(self, payload: Dict[str, Any]) -> None:
        # backlog monitoring
        q_len = len(self._agenda)
        if q_len > 50:
            self.logger.warning(f"Planner backlog {q_len} tasks")

    # ──────────────────────────────────────────────────────────────────────
    # Health / status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        with self._lock:
            fail_ratio = self._failed / max(1, self._executed + self._failed)
            healthy = fail_ratio < 0.1 and len(self._agenda) < 100
            return {
                "executed": self._executed,
                "failed": self._failed,
                "agenda_len": len(self._agenda),
                "healthy": healthy,
            }

    def get_status(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "agenda_len": len(self._agenda),
                "drives": {k: round(v, 2) for k, v in self._drives.items()},
            }

from grandnexus.planning.executive_planner import HTNMethod, PlanStep

def move_arm_expand(params):
    return [
        PlanStep("virt_gripper", {"action": "open"}),
        PlanStep("robot_arm", {"move_to": params["target"]}),
        PlanStep("virt_gripper", {"action": "close"}),
    ]

planner = nexus.get_module("executive_planner")
planner.register_method(HTNMethod("move_object", move_arm_expand))

# grandnexus/perception/filters/attention_filter.py
# ─────────────────────────────────────────────────────────────────────────────
"""
AttentionFilter — Dynamic Saliency & Perceptual Gating Layer
===========================================================

Capacités
─────────
• **Bottom-Up** : calcul de saillance (variance, nouveauté, intensité) par pilote
  de capteur ; combinaison en score ∈ [0-1].
• **Top-Down** : injection d’objectifs (features, régions d’intérêt, regex,
  embeddings) et de _homeostasis drives_ (FATIGUE, THERMAL…) pour biaiser
  la distribution d’attention.
• **Budget de bande passante** : limite la fréquence ou la taille des flux
  entrants selon la charge CPU et la _working-memory_ disponible.
• **Apprentissage** : maintient un histogramme de « gains informatifs » et
  renforce la probabilité de sélection de stimuli qui ont amélioré la reward.
• **Observabilité & self-diagnosis** : expose métriques de *drop-rate*,
  latence, taux de faux-positifs (via feedback).
• **Hot-swap rules** : ajout / retrait de filtres ou _spotlights_ en JSON RPC.
"""

from __future__ import annotations

import logging
import threading
import time
import uuid
from dataclasses import dataclass, field
from typing import Any, Dict, List, Tuple, Callable, Optional, Deque
from collections import deque, defaultdict

from grandnexus.core.nexus_core import NexusCore

# ─────────────────────────────────────────────────────────────────────────────
# 1. Structures auxiliaires
# ─────────────────────────────────────────────────────────────────────────────
@dataclass
class SpotlightRule:
    """Filtre Top-Down : garde ou rejette si condition match."""
    name: str
    matcher: Callable[[Dict[str, Any]], bool]
    boost: float = 0.3                # ajoute au score
    expiry_ts: Optional[float] = None


@dataclass
class FilterConfig:
    # Bande passante max (items/s) par capteur
    max_rate: Dict[str, float] = field(default_factory=lambda: defaultdict(lambda: 50.0))
    # Score seuil minimal pour laisser passer
    threshold: float = 0.4
    # Influence des drives [0-1] ⇒ modifie threshold
    drive_bias: Dict[str, float] = field(default_factory=lambda: {
        "FATIGUE": +0.2,      # fatigué ⇒ seuil ↑
        "HUNGER":  -0.1,      # batterie faible ⇒ veut stimuli pour recharge
        "THERMAL": +0.3,
    })
    history_sec: int = 30
    tick_channel: str = "fast"
    drive_source: str = "homeostasis_manager"
    perception_target: str = "perception_core"


# ─────────────────────────────────────────────────────────────────────────────
# 2. AttentionFilter principal
# ─────────────────────────────────────────────────────────────────────────────
class AttentionFilter:
    MODULE_NAME = "attention_filter"
    MSG_SENSOR = "sensor_data"
    MSG_DRIVE = "homeostasis_drive"

    def __init__(
        self,
        nexus_core: NexusCore,
        config: Optional[FilterConfig] = None,
    ):
        self.logger = logging.getLogger("GrandNexus.Perception.AttentionFilter")
        self.nexus_core = nexus_core
        self.config = config or FilterConfig()

        # Runtime
        self._lock = threading.RLock()
        self._running = False
        self._instance_id = str(uuid.uuid4())[:8]

        # Stats & state
        window = int(self.config.history_sec * max(self.config.max_rate.values()))
        self._hist_scores: Deque[float] = deque(maxlen=window)
        self._last_sent: Dict[str, float] = defaultdict(float)   # per driver
        self._drives: Dict[str, float] = {}
        self._spotlights: List[SpotlightRule] = []

        # Metrics
        self._accepted = 0
        self._dropped = 0

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ──────────────────────────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._running:
                return True
            self._running = True

        self.nexus_core.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["sensor_hub", "cognitive_clock", self.config.drive_source],
        )

        # Subscribe to ticks (for cleanup / rate reset)
        clock = self.nexus_core.get_module("cognitive_clock")
        if clock:
            clock.subscribe(self.config.tick_channel, self._on_tick)

        self.logger.info(f"AttentionFilter {self._instance_id} started")
        return True

    def stop(self) -> bool:
        with self._lock:
            self._running = False
        self.logger.info("AttentionFilter stopped")
        return True

    # ──────────────────────────────────────────────────────────────────────
    # Message entry-point
    # ──────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]) -> None:
        mtype = msg.get("type")
        if mtype == self.MSG_SENSOR:
            self._process_sensor(msg["content"])
        elif mtype == self.MSG_DRIVE:
            self._update_drives(msg["content"])

    # ──────────────────────────────────────────────────────────────────────
    # Sensor processing
    # ──────────────────────────────────────────────────────────────────────
    def _process_sensor(self, content: Dict[str, Any]) -> None:
        drv = content["driver_id"]
        now = time.time()

        # Rate limiting
        last = self._last_sent[drv]
        max_rate = self.config.max_rate[drv]
        if max_rate and (now - last) < (1.0 / max_rate):
            self._dropped += 1
            return

        # Score
        score = self._compute_saliency(content["data"])
        score = self._apply_spotlights(content, score)
        score = self._apply_drive_bias(score)

        self._hist_scores.append(score)

        if score >= self.config.threshold:
            self._accepted += 1
            self._last_sent[drv] = now
            self.nexus_core.send_message(
                source=self.MODULE_NAME,
                target=self.config.perception_target,
                message_type=self.MSG_SENSOR,
                content=content,
                priority=3,
            )
        else:
            self._dropped += 1

    # — saliency heuristics
    def _compute_saliency(self, data: Any) -> float:
        # Simple heuristics : variance / novelty
        try:
            if isinstance(data, dict) and "observation" in data:
                vals = data["observation"]
                if isinstance(vals, (list, tuple)):
                    return min(1.0, float(max(vals) - min(vals)))
            elif isinstance(data, (int, float)):
                return min(1.0, abs(float(data)) / 10.0)
        except Exception:
            pass
        return 0.1

    # — top-down spotlights
    def _apply_spotlights(self, msg: Dict[str, Any], score: float) -> float:
        boost = 0.0
        now = time.time()
        for rule in self._spotlights:
            if rule.expiry_ts and now > rule.expiry_ts:
                continue
            try:
                if rule.matcher(msg):
                    boost = max(boost, rule.boost)
            except Exception as exc:
                self.logger.error(f"Spotlight rule {rule.name} error: {exc}")
        return min(1.0, score + boost)

    # — homeostasis bias
    def _apply_drive_bias(self, score: float) -> float:
        adjusted = score
        for drive, bias in self.config.drive_bias.items():
            adjusted += bias * self._drives.get(drive, 0.0)
        return max(0.0, min(1.0, adjusted))

    # — drives update
    def _update_drives(self, drive: Dict[str, float]) -> None:
        with self._lock:
            self._drives = drive

    # ──────────────────────────────────────────────────────────────────────
    # Tick cleanup
    # ──────────────────────────────────────────────────────────────────────
    def _on_tick(self, payload: Dict[str, Any]) -> None:
        # Purge expired spotlights
        now = time.time()
        self._spotlights = [r for r in self._spotlights if not r.expiry_ts or r.expiry_ts > now]

    # ──────────────────────────────────────────────────────────────────────
    # Runtime API
    # ──────────────────────────────────────────────────────────────────────
    def add_spotlight(
        self,
        name: str,
        matcher: Callable[[Dict[str, Any]], bool],
        boost: float = 0.3,
        duration: float = 10.0,
    ) -> None:
        self._spotlights.append(
            SpotlightRule(name=name, matcher=matcher, boost=boost, expiry_ts=time.time() + duration)
        )
        self.logger.info(f"Added spotlight {name}")

    # ──────────────────────────────────────────────────────────────────────
    # Health / status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        total = self._accepted + self._dropped
        ratio = self._dropped / total if total else 0.0
        healthy = ratio < 0.8
        return {
            "accepted": self._accepted,
            "dropped": self._dropped,
            "drop_ratio": round(ratio, 3),
            "healthy": healthy,
        }

    def get_status(self) -> Dict[str, Any]:
        return {
            "hist_avg": round(sum(self._hist_scores) / max(1, len(self._hist_scores)), 3),
            "spotlights": [r.name for r in self._spotlights],
            "drives": {k: round(v, 2) for k, v in self._drives.items()},
        }

from grandnexus.core.nexus_core import NexusCore
