# grandnexus/memory/working.py
# ─────────────────────────────────────────────────────────────────────────
"""
WorkingMemory — Active Store with Decay & Semantic Retrieval
===========================================================

Caractéristiques
────────────────
• **Capacité bornée** (par nombre ou par taille) avec éviction LRU ⇢ salience.
• **Décroissance temporelle** : score(t) = salience₀ · e^(–λ·Δt) ajusté par
  les _drives_ homéostatiques (fatigue ⇒ λ↑).
• **Chunking & tagging** : chaque item est un `MemoryChunk` (dataclass) doté
  de : embedding facultatif, métadonnées, priorité, compteur d’accès.
• **Requêtes** :
  – par clé / id
  – par prédicat (lambda)
  – par similarité (cos θ) via backend d’embeddings externe (callback).
• **Consolidation** : flush périodique (tick lent) ⇢ `EpisodicMemory`; règle
  configurable (age, importance).
• **Observabilité / health** ( taux hit/miss, utilisation, avg latency ).
• **Plug-in vector store** : fallback numpy / Annoy / Faiss ; injection via DI.
"""

from __future__ import annotations

import logging
import threading
import time
import uuid
import math
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Callable, Deque, Tuple
from collections import deque, defaultdict

import numpy as np

from grandnexus.core.nexus_core import NexusCore

# ─────────────────────────────────────────────────────────────────────────
# 1. Structures
# ─────────────────────────────────────────────────────────────────────────
@dataclass
class MemoryChunk:
    """Représentation élémentaire en mémoire de travail."""
    chunk_id: str
    data: Any
    timestamp: float
    salience: float = 1.0
    embedding: Optional[np.ndarray] = None
    metadata: Dict[str, Any] = field(default_factory=dict)
    access_count: int = 0


@dataclass
class WMConfig:
    capacity: int = 2048                     # max items
    decay_half_life: float = 30.0            # s (λ = ln2 / t½)
    consolidation_age: float = 120.0         # s → episodic
    max_query_results: int = 8
    tick_channel: str = "fast"
    drive_source: str = "homeostasis_manager"
    episodic_target: str = "episodic_memory"
    embedding_fn: Optional[Callable[[Any], np.ndarray]] = None


# ─────────────────────────────────────────────────────────────────────────
# 2. WorkingMemory class
# ─────────────────────────────────────────────────────────────────────────
class WorkingMemory:
    MODULE_NAME = "working_memory"

    def __init__(
        self,
        nexus_core: NexusCore,
        config: Optional[WMConfig] = None,
    ):
        self.logger = logging.getLogger("GrandNexus.Memory.WorkingMemory")
        self.nexus_core = nexus_core
        self.config = config or WMConfig()

        # Storage
        self._lock = threading.RLock()
        self._store: Dict[str, MemoryChunk] = {}
        self._lru_order: Deque[str] = deque()

        # Stats
        self._hit = 0
        self._miss = 0

        # Drives
        self._drives: Dict[str, float] = {}

        # Runtime
        self._running = False
        self._instance_id = str(uuid.uuid4())[:8]

    # ─────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ─────────────────────────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._running:
                return True
            self._running = True

        # Register
        self.nexus_core.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock", self.config.drive_source],
        )

        # Subscribe clock
        clock = self.nexus_core.get_module("cognitive_clock")
        if clock:
            clock.subscribe(self.config.tick_channel, self._on_tick)

        self.logger.info(f"WorkingMemory {self._instance_id} started")
        return True

    def stop(self) -> bool:
        with self._lock:
            self._running = False
        return True

    # ─────────────────────────────────────────────────────────────────────
    # Insertion
    # ─────────────────────────────────────────────────────────────────────
    def put(
        self,
        data: Any,
        salience: float = 1.0,
        metadata: Optional[Dict[str, Any]] = None,
        embedding: Optional[np.ndarray] = None,
    ) -> str:
        if embedding is None and self.config.embedding_fn:
            try:
                embedding = self.config.embedding_fn(data)
            except Exception as exc:
                self.logger.warning(f"Embedding failure: {exc}")

        chunk = MemoryChunk(
            chunk_id=str(uuid.uuid4())[:8],
            data=data,
            timestamp=time.time(),
            salience=salience,
            embedding=embedding,
            metadata=metadata or {},
        )

        with self._lock:
            # Eviction if necessary
            if len(self._store) >= self.config.capacity:
                self._evict_one()

            self._store[chunk.chunk_id] = chunk
            self._lru_order.append(chunk.chunk_id)
        return chunk.chunk_id

    # ─────────────────────────────────────────────────────────────────────
    # Retrieval
    # ─────────────────────────────────────────────────────────────────────
    def get(
        self,
        chunk_id: str,
    ) -> Optional[MemoryChunk]:
        with self._lock:
            chunk = self._store.get(chunk_id)
            if chunk:
                self._hit += 1
                chunk.access_count += 1
                chunk.timestamp = time.time()
                # move to end (most recent)
                try:
                    self._lru_order.remove(chunk_id)
                except ValueError:
                    pass
                self._lru_order.append(chunk_id)
            else:
                self._miss += 1
        return chunk

    def query(
        self,
        predicate: Optional[Callable[[MemoryChunk], bool]] = None,
        embedding: Optional[np.ndarray] = None,
        top_k: Optional[int] = None,
    ) -> List[MemoryChunk]:
        results: List[Tuple[float, MemoryChunk]] = []
        now = time.time()
        with self._lock:
            for ch in self._store.values():
                if predicate and not predicate(ch):
                    continue

                score = self._current_salience(ch, now)
                # embedding similarity boost
                if embedding is not None and ch.embedding is not None:
                    sim = self._cos_sim(embedding, ch.embedding)
                    score += sim
                results.append((score, ch))

        results.sort(key=lambda x: x[0], reverse=True)
        k = top_k or self.config.max_query_results
        out = [c for _, c in results[:k]]
        for c in out:
            self.get(c.chunk_id)   # update LRU + stats
        return out

    # ─────────────────────────────────────────────────────────────────────
    # Internal utilities
    # ─────────────────────────────────────────────────────────────────────
    def _evict_one(self) -> None:
        """LRU with salience fallback."""
        while self._lru_order:
            cid = self._lru_order.popleft()
            if cid in self._store:
                del self._store[cid]
                self.logger.debug(f"Evicted chunk {cid}")
                return

    def _current_salience(self, chunk: MemoryChunk, now: float) -> float:
        age = now - chunk.timestamp
        λ = math.log(2) / self.config.decay_half_life
        # Drive-modulated decay
        λ *= 1.0 + self._drives.get("FATIGUE", 0.0)
        return chunk.salience * math.exp(-λ * age)

    @staticmethod
    def _cos_sim(a: np.ndarray, b: np.ndarray) -> float:
        if a is None or b is None:
            return 0.0
        return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b) + 1e-9))

    # ─────────────────────────────────────────────────────────────────────
    # Tick & consolidation
    # ─────────────────────────────────────────────────────────────────────
    def _on_tick(self, payload: Dict[str, Any]) -> None:
        now = time.time()
        to_consolidate = []
        with self._lock:
            for cid in list(self._store.keys()):
                ch = self._store[cid]
                # Decay update & consolidation
                if (now - ch.timestamp) >= self.config.consolidation_age:
                    to_consolidate.append(ch)
                    del self._store[cid]
                    try:
                        self._lru_order.remove(cid)
                    except ValueError:
                        pass

        # Send to EpisodicMemory
        for ch in to_consolidate:
            self.nexus_core.send_message(
                source=self.MODULE_NAME,
                target=self.config.episodic_target,
                message_type="episodic_ingest",
                content={
                    "chunk_id": ch.chunk_id,
                    "data": ch.data,
                    "metadata": ch.metadata,
                    "embedding": ch.embedding.tolist() if ch.embedding is not None else None,
                    "timestamp": ch.timestamp,
                },
                priority=5,
            )

    # ─────────────────────────────────────────────────────────────────────
    # Drives update via message
    # ─────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]) -> None:
        if msg.get("type") == "homeostasis_drive":
            with self._lock:
                self._drives = msg["content"]

    # ─────────────────────────────────────────────────────────────────────
    # Health / status
    # ─────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        with self._lock:
            miss_ratio = self._miss / max(1, self._hit + self._miss)
            healthy = len(self._store) < self.config.capacity and miss_ratio < 0.5
            return {
                "items": len(self._store),
                "hit": self._hit,
                "miss": self._miss,
                "miss_ratio": round(miss_ratio, 3),
                "healthy": healthy,
            }

    def get_status(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "items": len(self._store),
                "lru_len": len(self._lru_order),
                "drives": {k: round(v, 2) for k, v in self._drives.items()},
            }

from grandnexus.core.nexus_core import NexusCore
from grandnexus.clock.cognitive_clock import CognitiveClock
from grandnexus.memory.working import WorkingMemory

nexus = NexusCore()
CognitiveClock(nexus).start()
wm = WorkingMemory(nexus).start()

chunk_id = wm.put({"text": "The quick brown fox"}, salience=0.8)

# Recherche par predicate
fox_chunks = wm.query(predicate=lambda c: "fox" in c.data["text"])
print([c.chunk_id for c in fox_chunks])

# grandnexus/memory/semantic.py
# ─────────────────────────────────────────────────────────────────────────
"""
SemanticMemory — Hybrid Vector + Graph Knowledge Store for GrandNexus
=====================================================================

Dépendances externes :
    pip install pgvector psycopg2-binary neo4j annoy sentence-transformers
"""

from __future__ import annotations

import logging, threading, time, uuid, os, json, math, contextlib
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple, Sequence, Iterable
import numpy as np

# Embedding
from sentence_transformers import SentenceTransformer                  # type: ignore

# Vector back-end
with contextlib.suppress(ImportError):
    import psycopg2, psycopg2.extras                                    # type: ignore
    from pgvector.psycopg2 import register_vector                      # type: ignore
with contextlib.suppress(ImportError):
    from annoy import AnnoyIndex                                        # type: ignore

# Graph back-end
with contextlib.suppress(ImportError):
    from neo4j import GraphDatabase                                     # type: ignore

from grandnexus.core.nexus_core import NexusCore

# ─────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ─────────────────────────────────────────────────────────────────────────
@dataclass
class Neo4jCfg:
    uri: str = "bolt://localhost:7687"
    user: str = "neo4j"
    password: str = "password"


@dataclass
class PGVectorCfg:
    dsn: str = "postgresql://user:pass@localhost:5432/gnx"
    table: str = "semantic_vectors"
    dim: int = 768
    metric: str = "cosine"                     # pgvector: cosine|l2|inner


@dataclass
class AnnoyCfg:
    dim: int = 768
    n_trees: int = 10
    metric: str = "angular"


@dataclass
class SemMemConfig:
    embed_model: str = "sentence-transformers/all-MiniLM-L6-v2"
    batch_size: int = 64
    pg: Optional[PGVectorCfg] = PGVectorCfg()
    neo4j: Optional[Neo4jCfg] = Neo4jCfg()
    annoy: Optional[AnnoyCfg] = AnnoyCfg()
    consolidate_every: float = 30.0                # s
    tick_channel: str = "slow"
    safety_guard: Optional[str] = "safety_guard"


# ─────────────────────────────────────────────────────────────────────────
# 2. SemanticMemory
# ─────────────────────────────────────────────────────────────────────────
class SemanticMemory:
    MODULE_NAME = "semantic_memory"
    MSG_QUERY = "semantic_query"
    MSG_UPSERT = "semantic_upsert"

    def __init__(self, nexus_core: NexusCore, cfg: Optional[SemMemConfig] = None):
        self.logger = logging.getLogger("GrandNexus.Memory.SemanticMemory")
        self.nexus = nexus_core
        self.cfg = cfg or SemMemConfig()

        # Embedding model (thread-safe)
        self._model = SentenceTransformer(self.cfg.embed_model)

        # Vector store
        self._pg_conn: Optional["psycopg2.extensions.connection"] = None
        self._ann: Optional["AnnoyIndex"] = None
        self._ann_map: Dict[int, str] = {}

        # Graph store
        self._neo4j = None

        # Runtime
        self._lock = threading.RLock()
        self._running = False
        self._last_consolidate = 0.0
        self._pending_ann: List[Tuple[str, np.ndarray]] = []  # chunk_id, emb
        self._instance_id = str(uuid.uuid4())[:8]

        # Stats
        self._q_latency: List[float] = []
        self._upserts = 0

    # ─────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ─────────────────────────────────────────────────────────────────────
    def start(self) -> bool:
        with self._lock:
            if self._running:
                return True
            self._running = True

        self._init_pgvector()
        self._init_neo4j()
        self._init_annoy()

        # Enregistrement NexusCore
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock"],
        )

        # Tick subscription pour consolidation ANN ↔ PG
        clk = self.nexus.get_module("cognitive_clock")
        if clk:
            clk.subscribe(self.cfg.tick_channel, self._on_tick)

        self.logger.info(f"SemanticMemory {self._instance_id} started")
        return True

    def stop(self) -> bool:
        self._running = False
        if self._pg_conn:
            self._pg_conn.close()
        if self._neo4j:
            self._neo4j.close()
        return True

    # ─────────────────────────────────────────────────────────────────────
    # Backend initialisation
    # ─────────────────────────────────────────────────────────────────────
    def _init_pgvector(self):
        if not self.cfg.pg:
            return
        try:
            self._pg_conn = psycopg2.connect(self.cfg.pg.dsn)
            register_vector(self._pg_conn)
            cur = self._pg_conn.cursor()
            cur.execute(
                f"""
                CREATE TABLE IF NOT EXISTS {self.cfg.pg.table} (
                    id TEXT PRIMARY KEY,
                    embedding VECTOR({self.cfg.pg.dim}),
                    metadata JSONB
                );
                """
            )
            cur.execute(f"CREATE INDEX IF NOT EXISTS idx_vec ON {self.cfg.pg.table} USING ivfflat (embedding vector_{self.cfg.pg.metric});")
            self._pg_conn.commit()
        except Exception as exc:
            self.logger.error(f"PGVector init failed: {exc}")
            self._pg_conn = None

    def _init_annoy(self):
        if not AnnoyCfg:
            return
        self._ann = AnnoyIndex(self.cfg.annoy.dim, self.cfg.annoy.metric)
        # will rebuild periodically

    def _init_neo4j(self):
        if not self.cfg.neo4j:
            return
        try:
            self._neo4j = GraphDatabase.driver(
                self.cfg.neo4j.uri, auth=(self.cfg.neo4j.user, self.cfg.neo4j.password)
            )
            with self._neo4j.session() as sess:
                sess.run("CREATE CONSTRAINT IF NOT EXISTS FOR (n:Knowledge) REQUIRE n.id IS UNIQUE")
        except Exception as exc:
            self.logger.error(f"Neo4j init failed: {exc}")
            self._neo4j = None

    # ─────────────────────────────────────────────────────────────────────
    # Public API – upsert & query
    # ─────────────────────────────────────────────────────────────────────
    def upsert_document(
        self,
        text: str,
        metadata: Optional[Dict[str, Any]] = None,
        triplets: Optional[List[Tuple[str, str, str]]] = None,
    ) -> str:
        doc_id = str(uuid.uuid4())[:8]
        emb = self._model.encode(text)
        meta = metadata or {}

        # Safety guard pre-check
        if self.cfg.safety_guard:
            sg = self.nexus.get_module(self.cfg.safety_guard)
            if sg and hasattr(sg, "is_allowed") and not sg.is_allowed(text, meta):
                self.logger.warning("SafetyGuard blocked upsert")
                return ""

        # PGVector
        if self._pg_conn:
            try:
                cur = self._pg_conn.cursor()
                cur.execute(
                    f"INSERT INTO {self.cfg.pg.table} (id, embedding, metadata) VALUES (%s, %s, %s) ON CONFLICT (id) DO NOTHING",
                    (doc_id, emb.tolist(), json.dumps(meta)),
                )
                self._pg_conn.commit()
            except Exception as exc:
                self.logger.error(f"PG upsert error: {exc}")

        # Annoy (lazy)
        if self._ann is not None:
            self._pending_ann.append((doc_id, emb))

        # Neo4j triplets
        if triplets and self._neo4j:
            with self._neo4j.session() as s:
                for (sub, pred, obj) in triplets:
                    s.run(
                        """
                        MERGE (s:Entity {name:$sub})
                        MERGE (o:Entity {name:$obj})
                        MERGE (s)-[:REL {type:$pred, doc_id:$doc}]->(o)
                        """,
                        sub=sub, obj=obj, pred=pred, doc=doc_id,
                    )
                s.run("MERGE (d:Knowledge {id:$id}) SET d.text=$txt", id=doc_id, txt=text)

        with self._lock:
            self._upserts += 1
        return doc_id

    def semantic_query(
        self,
        text: str,
        top_k: int = 5,
    ) -> List[Dict[str, Any]]:
        start = time.perf_counter()
        emb = self._model.encode(text)

        results: List[Tuple[float, str, Dict[str, Any]]] = []

        # PGVector search
        if self._pg_conn:
            cur = self._pg_conn.cursor(cursor_factory=psycopg2.extras.DictCursor)
            cur.execute(
                f"""
                SELECT id, metadata, 1 - (embedding <=> %s) AS score
                FROM {self.cfg.pg.table}
                ORDER BY embedding <=> %s
                LIMIT %s
                """,
                (emb.tolist(), emb.tolist(), top_k * 2),
            )
            for row in cur.fetchall():
                results.append((row["score"], row["id"], dict(row["metadata"])))

        # Annoy fallback
        elif self._ann and self._ann.get_n_items():
            idxs, dists = self._ann.get_nns_by_vector(emb, top_k * 2, include_distances=True)
            for dist, idx in zip(dists, idxs):
                cid = self._ann_map.get(idx)
                results.append((1 - dist, cid, {}))

        # Sort & truncate
        results.sort(key=lambda x: x[0], reverse=True)
        out = []
        for score, cid, meta in results[: top_k]:
            trip = self._fetch_triplets(cid)
            out.append(
                {"doc_id": cid, "score": round(float(score), 3), "metadata": meta, "triplets": trip}
            )

        self._q_latency.append(time.perf_counter() - start)
        return out

    # ─────────────────────────────────────────────────────────────────────
    # Triplet fetch helper
    # ─────────────────────────────────────────────────────────────────────
    def _fetch_triplets(self, doc_id: str) -> List[Tuple[str, str, str]]:
        if not self._neo4j:
            return []
        with self._neo4j.session() as s:
            res = s.run(
                """
                MATCH (s:Entity)-[r:REL {doc_id:$doc}]->(o:Entity)
                RETURN s.name AS sub, r.type AS pred, o.name AS obj
                """,
                doc=doc_id,
            )
            return [(r["sub"], r["pred"], r["obj"]) for r in res]

    # ─────────────────────────────────────────────────────────────────────
    # Message interface
    # ─────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]) -> None:
        mtype = msg.get("type")
        if mtype == self.MSG_UPSERT:
            self.upsert_document(**msg["content"])
        elif mtype == self.MSG_QUERY:
            res = self.semantic_query(**msg["content"])
            # Répondre à la source si demandé
            if "reply_to" in msg:
                self.nexus.send_message(
                    source=self.MODULE_NAME,
                    target=msg["reply_to"],
                    message_type="semantic_response",
                    content=res,
                )

    # ─────────────────────────────────────────────────────────────────────
    # Tick consolidation (annoy build)
    # ─────────────────────────────────────────────────────────────────────
    def _on_tick(self, _):
        now = time.time()
        if self._ann is None or not self._pending_ann:
            return
        if now - self._last_consolidate < self.cfg.consolidate_every:
            return

        with self._lock:
            pending = list(self._pending_ann)
            self._pending_ann.clear()

        for cid, emb in pending:
            idx = self._ann.get_n_items()
            self._ann.add_item(idx, emb)
            self._ann_map[idx] = cid
        self._ann.build(self.cfg.annoy.n_trees)
        self._last_consolidate = now
        self.logger.info(f"Annoy index rebuilt with {self._ann.get_n_items()} items")

    # ─────────────────────────────────────────────────────────────────────
    # Health / status
    # ─────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        lat = sum(self._q_latency) / len(self._q_latency) if self._q_latency else 0.0
        healthy = (self._pg_conn or self._ann) and (self._neo4j is not None)
        return {
            "latency_avg_ms": round(lat * 1_000, 2),
            "upserts": self._upserts,
            "vector_backend": "pgvector" if self._pg_conn else ("annoy" if self._ann else "none"),
            "graph_backend": bool(self._neo4j),
            "healthy": healthy,
        }

    def get_status(self) -> Dict[str, Any]:
        return {
            "items_vector": self._ann.get_n_items() if self._ann else "N/A",
            "upserts": self._upserts,
        }

# grandnexus/security/safety_guard.py
# ──────────────────────────────────────────────────────────────────────────
"""
SafetyGuard — Alignment, Compliance & Action Safety Layer
=========================================================

Dépendances externes (optionnelles) :
    pip install pyopa pydantic[dotenv] prometheus-client
"""

from __future__ import annotations

import logging, re, time, uuid, hashlib, json, threading, os
from dataclasses import dataclass, field
from enum import Enum, auto
from typing import Any, Dict, List, Callable, Optional, Tuple

from grandnexus.core.nexus_core import NexusCore

# OPA optional
try:
    import pyopa                                 # type: ignore
    OPA_AVAILABLE = True
except ImportError:
    OPA_AVAILABLE = False

# Prometheus
try:
    from prometheus_client import Counter, Gauge
    METRIC_BLOCKED = Counter("gnx_guard_blocked", "Number of blocked items", ["reason"])
    METRIC_ALLOWED = Counter("gnx_guard_allowed", "Number of allowed items")
    METRIC_RISK    = Gauge("gnx_guard_risk", "Latest risk score")
except ImportError:
    METRIC_BLOCKED = METRIC_ALLOWED = METRIC_RISK = None


# ──────────────────────────────────────────────────────────────────────────
# 1. Enum & Config
# ──────────────────────────────────────────────────────────────────────────
class Risk(Enum):
    LOW = auto()
    MEDIUM = auto()
    HIGH = auto()
    CRITICAL = auto()


@dataclass
class GuardConfig:
    policy_file: Optional[str] = None               # .rego ou .yaml
    log_file: str = "safety_audit.jsonl"
    block_threshold: Risk = Risk.HIGH
    anonymise_patterns: List[str] = field(default_factory=lambda: [
        r"\b([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})\b",   # emails
        r"\b(\+?\d[\d \-\(\)]{6,})\b",                    # phone
    ])
    max_torque_nm: float = 50.0                   # exemple contrainte action
    max_velocity_m_s: float = 1.5
    opa_entrypoint: str = "policy/allow"

# ──────────────────────────────────────────────────────────────────────────
# 2. SafetyGuard principale
# ──────────────────────────────────────────────────────────────────────────
class SafetyGuard:
    MODULE_NAME = "safety_guard"

    def __init__(self, nexus_core: NexusCore, cfg: Optional[GuardConfig] = None):
        self.logger = logging.getLogger("GrandNexus.Security.SafetyGuard")
        self.nexus = nexus_core
        self.cfg = cfg or GuardConfig()

        # Runtime
        self._lock = threading.RLock()
        self._running = False

        # Audit log file handle
        self._log_fh = open(self.cfg.log_file, "a", encoding="utf8")

        # OPA
        self._opa_ctx = None
        if self.cfg.policy_file and OPA_AVAILABLE and self.cfg.policy_file.endswith(".rego"):
            with open(self.cfg.policy_file, "r", encoding="utf8") as f:
                rego_code = f.read()
            self._opa_ctx = pyopa.load(rego_code)

    # ─────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ─────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running:
            return
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=[],
        )
        self.logger.info("SafetyGuard started")

    def stop(self):
        self._running = False
        self._log_fh.close()

    # ─────────────────────────────────────────────────────────────────────
    # Main public API
    # ─────────────────────────────────────────────────────────────────────
    # 1) Content (text / doc) --------------------------------------------------
    def is_allowed(self, text: str, metadata: Dict[str, Any] | None = None) -> bool:
        """
        Retourne True si la conservation / diffusion est autorisée.
        Si bloqué : journalise et incrémente métriques.
        """
        meta = metadata or {}
        risk = self._assess_risk_text(text, meta)

        if METRIC_RISK:
            METRIC_RISK.set(risk.value)

        if risk.value >= self.cfg.block_threshold.value:
            self._audit("BLOCK", risk, text=text, meta=meta)
            if METRIC_BLOCKED:
                METRIC_BLOCKED.labels(reason=risk.name).inc()
            return False

        # anonymisation soft
        text_an = self._anonymise(text) if risk == Risk.HIGH else text
        self._audit("ALLOW", risk, text=text_an, meta=meta)
        if METRIC_ALLOWED:
            METRIC_ALLOWED.inc()
        return True

    # 2) Action command --------------------------------------------------------
    def validate_action(self, command: Dict[str, Any]) -> bool:
        """
        Vérifie contraintes de sûreté avant dispatch à ActuatorHub.
        """
        risk = self._assess_risk_action(command)
        if risk.value >= self.cfg.block_threshold.value:
            self._audit("BLOCK_ACTION", risk, action=command)
            if METRIC_BLOCKED:
                METRIC_BLOCKED.labels(reason="ACTION").inc()
            return False
        self._audit("ALLOW_ACTION", risk, action=command)
        return True

    # ─────────────────────────────────────────────────────────────────────
    # Risk assessment helpers
    # ─────────────────────────────────────────────────────────────────────
    def _assess_risk_text(self, text: str, meta: Dict[str, Any]) -> Risk:
        # 1) OPA policy
        if self._opa_ctx:
            decision = pyopa.evaluate(self._opa_ctx, self.cfg.opa_entrypoint, {"text": text, "meta": meta})
            if decision is False:
                return Risk.CRITICAL
            elif isinstance(decision, (int, float)):
                return self._map_score(decision)

        # 2) simple heuristics
        if len(text) > 10_000:
            return Risk.HIGH
        if any(re.search(pat, text, re.I) for pat in self.cfg.anonymise_patterns):
            return Risk.MEDIUM
        return Risk.LOW

    def _assess_risk_action(self, cmd: Dict[str, Any]) -> Risk:
        # Example kinematic check
        torque = cmd.get("torque_nm", 0.0)
        speed = cmd.get("speed_m_s", 0.0)
        if torque > self.cfg.max_torque_nm or speed > self.cfg.max_velocity_m_s:
            return Risk.CRITICAL
        return Risk.LOW

    @staticmethod
    def _map_score(score: float) -> Risk:
        if score >= 0.9:
            return Risk.CRITICAL
        if score >= 0.7:
            return Risk.HIGH
        if score >= 0.4:
            return Risk.MEDIUM
        return Risk.LOW

    # ─────────────────────────────────────────────────────────────────────
    # Utilities
    # ─────────────────────────────────────────────────────────────────────
    def _anonymise(self, text: str) -> str:
        out = text
        for pat in self.cfg.anonymise_patterns:
            out = re.sub(pat, "[REDACTED]", out, flags=re.I)
        return out

    def _audit(self, verdict: str, risk: Risk, **payload):
        record = {
            "ts": time.time(),
            "verdict": verdict,
            "risk": risk.name,
            "payload": payload,
            "id": str(uuid.uuid4())[:8],
        }
        with self._lock:
            self._log_fh.write(json.dumps(record, ensure_ascii=False) + "\n")
            self._log_fh.flush()
        self.logger.debug(f"Audit: {verdict} risk={risk.name}")

    # ─────────────────────────────────────────────────────────────────────
    # Message interface
    # ─────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]) -> None:
        mtype = msg.get("type")
        if mtype == "check_action":
            allowed = self.validate_action(msg["content"])
            self.nexus.send_message(
                source=self.MODULE_NAME,
                target=msg["source"],
                message_type="check_action_response",
                content={"allowed": allowed},
            )

    # ─────────────────────────────────────────────────────────────────────
    # Health / status
    # ─────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        return {
            "policy_source": self.cfg.policy_file or "internal",
            "opa": bool(self._opa_ctx),
            "log_file": self.cfg.log_file,
            "healthy": True,
        }

    def get_status(self) -> Dict[str, Any]:
        return {"block_threshold": self.cfg.block_threshold.name}

from grandnexus.security.safety_guard import SafetyGuard, GuardConfig
from grandnexus.core.nexus_core import NexusCore

nexus = NexusCore()
guard = SafetyGuard(nexus, GuardConfig(block_threshold=Risk.MEDIUM))
guard.start()

print(guard.is_allowed("Contact me at john.doe@example.com", {}))   # False (PII)
print(guard.validate_action({"torque_nm": 10, "speed_m_s": 0.5}))   # True

# grandnexus/metacognition/self_model.py
# ─────────────────────────────────────────────────────────────────────────
"""
SelfModelService — Structured Body-Schema & Capability Registry
==============================================================

• Représente le « moi » logiciel + matériel (robots, GPU, réseau).
• Valide en temps réel qu’une action planifiée / exécutée respecte les contraintes
  cinématiques, énergétiques, de sécurité et de licence.
• Réserve des ressources (GPU, API-tokens, bras robot) avec timeout et rollback.
• Fournit un flux de mises à jour (pub-sub) pour le raisonnement contre-factuel.
"""

from __future__ import annotations

import logging, time, threading, uuid, math
from dataclasses import dataclass, field
from typing import Dict, Any, List, Optional, Callable
from enum import Enum, auto

from grandnexus.core.nexus_core import NexusCore

# ─────────────────────────────────────────────────────────────────────────
# 1. Énumérations & structures
# ─────────────────────────────────────────────────────────────────────────
class ResourceType(Enum):
    CPU = auto()
    GPU = auto()
    MEMORY = auto()
    BATTERY = auto()
    ARM = auto()
    GRIPPER = auto()
    NETWORK = auto()
    LICENSE = auto()


@dataclass
class JointState:
    name: str
    position_deg: float
    velocity_deg_s: float
    torque_nm: float
    limits: Dict[str, float]


@dataclass
class ResourceQuota:
    max_units: float
    reserved: float = 0.0
    last_update: float = field(default_factory=time.time)


@dataclass
class SelfModelConfig:
    publish_interval: float = 2.0             # s
    tick_channel: str = "slow"
    guard_module: str = "safety_guard"


# ─────────────────────────────────────────────────────────────────────────
# 2. Service principal
# ─────────────────────────────────────────────────────────────────────────
class SelfModelService:
    MODULE_NAME = "self_model_service"
    MSG_STATE = "self_state"

    def __init__(self, nexus: NexusCore, cfg: Optional[SelfModelConfig] = None):
        self.logger = logging.getLogger("GrandNexus.Meta.SelfModel")
        self.nexus = nexus
        self.cfg = cfg or SelfModelConfig()

        # Mutex
        self._lock = threading.RLock()

        # Runtime maps
        self._joints: Dict[str, JointState] = {}
        self._resources: Dict[ResourceType, ResourceQuota] = {
            ResourceType.CPU: ResourceQuota(max_units=1.0),
            ResourceType.GPU: ResourceQuota(max_units=1.0),
            ResourceType.MEMORY: ResourceQuota(max_units=1.0),
            ResourceType.BATTERY: ResourceQuota(max_units=1.0),
        }

        # Publipostage
        self._last_pub = 0.0
        self._running = False
        self._instance_id = str(uuid.uuid4())[:8]

    # ─────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ─────────────────────────────────────────────────────────────────────
    def start(self):
        with self._lock:
            if self._running:
                return True
            self._running = True

        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock"],
        )

        clk = self.nexus.get_module("cognitive_clock")
        if clk:
            clk.subscribe(self.cfg.tick_channel, self._on_tick)

        self.logger.info(f"SelfModelService {self._instance_id} started")
        return True

    def stop(self):
        self._running = False
        return True

    # ─────────────────────────────────────────────────────────────────────
    # Public API
    # ─────────────────────────────────────────────────────────────────────
    def update_joint(self, name: str, pos: float, vel: float, tq: float, limits: Dict[str, float]):
        with self._lock:
            self._joints[name] = JointState(name, pos, vel, tq, limits)

    def reserve(self, rtype: ResourceType, units: float, ttl: float = 5.0) -> bool:
        with self._lock:
            q = self._resources.setdefault(rtype, ResourceQuota(max_units=units))
            if q.reserved + units > q.max_units:
                return False
            q.reserved += units
            q.last_update = time.time()
        # Schedule release (simple thread)
        threading.Timer(ttl, self.release, args=[rtype, units]).start()
        return True

    def release(self, rtype: ResourceType, units: float):
        with self._lock:
            q = self._resources.get(rtype)
            if q:
                q.reserved = max(0.0, q.reserved - units)
                q.last_update = time.time()

    def is_action_safe(self, action: Dict[str, Any]) -> bool:
        """
        Vérifie cinématique + ressources avant exécution.
        Délégué partiel à SafetyGuard si présent.
        """
        guard = self.nexus.get_module(self.cfg.guard_module)
        if guard and hasattr(guard, "validate_action"):
            return guard.validate_action(action)

        # fallback simple : limite vitesse/torque
        jid = action.get("joint")
        if jid and jid in self._joints:
            st = self._joints[jid]
            max_v = st.limits.get("vel_deg_s", 180)
            max_t = st.limits.get("torque_nm", 50)
            if abs(action.get("velocity_deg_s", 0)) > max_v:
                return False
            if abs(action.get("torque_nm", 0)) > max_t:
                return False
        return True

    def get_state(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "joints": {n: st.__dict__ for n, st in self._joints.items()},
                "resources": {rt.name: q.__dict__ for rt, q in self._resources.items()},
            }

    # ─────────────────────────────────────────────────────────────────────
    # Tick publication
    # ─────────────────────────────────────────────────────────────────────
    def _on_tick(self, _payload):
        now = time.time()
        if now - self._last_pub >= self.cfg.publish_interval:
            state = self.get_state()
            self.nexus.send_message(
                source=self.MODULE_NAME,
                target="monitor",                    # module de monitoring générique
                message_type=self.MSG_STATE,
                content=state,
                priority=6,
            )
            self._last_pub = now

    # ─────────────────────────────────────────────────────────────────────
    # Message interface
    # ─────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]) -> None:
        if msg.get("type") == "query_self_state":
            self.nexus.send_message(
                source=self.MODULE_NAME,
                target=msg["source"],
                message_type="self_state_response",
                content=self.get_state(),
            )

    # ─────────────────────────────────────────────────────────────────────
    # Health & status
    # ─────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "joints": len(self._joints),
                "resources": {r.name: q.reserved / q.max_units for r, q in self._resources.items()},
                "healthy": True,
            }

    def get_status(self) -> Dict[str, Any]:
        return self.get_state()

from grandnexus.core.nexus_core import NexusCore
from grandnexus.clock.cognitive_clock import CognitiveClock
from grandnexus.metacognition.self_model import SelfModelService, ResourceType

nexus = NexusCore()
CognitiveClock(nexus).start()
self_model = SelfModelService(nexus).start()

# Enregistrer articulation
self_model.update_joint("elbow", pos=10, vel=0, tq=0, limits={"vel_deg_s": 180, "torque_nm": 30})

# Réserver 0.5 GPU pendant 3 s
print(self_model.reserve(ResourceType.GPU, 0.5, ttl=3.0))  # → True

# Vérifier sûreté action
action = {"joint": "elbow", "velocity_deg_s": 90, "torque_nm": 10}
print(self_model.is_action_safe(action))                   # → True

# grandnexus/ops/metrics_exporter.py
# ─────────────────────────────────────────────────────────────────────────
"""
MetricsExporter — Prometheus & OTEL bridge for GrandNexus
=========================================================

Dépendances externes :
    pip install prometheus-client opentelemetry-api opentelemetry-sdk
"""

from __future__ import annotations

import logging, time, threading, socket
from dataclasses import dataclass
from typing import Dict, Any, Optional

from grandnexus.core.nexus_core import NexusCore

# Prometheus
from prometheus_client import (
    start_http_server,
    Gauge,
    Counter,
    Summary,
    CollectorRegistry,
    CONTENT_TYPE_LATEST,
    exposition,
)

# OpenTelemetry
from opentelemetry import metrics
from opentelemetry.sdk.metrics import MeterProvider
from opentelemetry.sdk.metrics.export import (
    ConsoleMetricExporter,
    PeriodicExportingMetricReader,
)

# ─────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ─────────────────────────────────────────────────────────────────────────
@dataclass
class ExporterConfig:
    port: int = 9095                           # Port HTTP /metrics
    scrape_interval: float = 5.0               # s
    otel_enabled: bool = False
    otel_interval: float = 15.0                # s
    otel_export_console: bool = True
    tick_channel: str = "slow"


# ─────────────────────────────────────────────────────────────────────────
# 2. Exporter principal
# ─────────────────────────────────────────────────────────────────────────
class MetricsExporter:
    MODULE_NAME = "metrics_exporter"

    def __init__(self, nexus: NexusCore, cfg: Optional[ExporterConfig] = None):
        self.logger = logging.getLogger("GrandNexus.Ops.MetricsExporter")
        self.nexus = nexus
        self.cfg = cfg or ExporterConfig()

        # Prom registry
        self.prom_reg = CollectorRegistry(auto_describe=True)

        # Core metrics
        self.g_module_up = Gauge(
            "gnx_module_up",
            "1 if module registered, 0 otherwise",
            ["module"],
            registry=self.prom_reg,
        )
        self.g_module_health = Gauge(
            "gnx_module_health",
            "Health ratio per module (0-1) if available",
            ["module"],
            registry=self.prom_reg,
        )
        self.g_queue_size = Gauge(
            "gnx_core_queue_size",
            "Size of NexusCore message queue",
            registry=self.prom_reg,
        )
        self.s_scrape_latency = Summary(
            "gnx_metrics_scrape_seconds",
            "Latency of scraping health_check()",
            registry=self.prom_reg,
        )
        self.c_scrape_errors = Counter(
            "gnx_metrics_scrape_errors_total",
            "Errors while scraping metrics",
            registry=self.prom_reg,
        )

        # OTEL metrics
        if self.cfg.otel_enabled:
            self._init_otel()

        # Runtime
        self._running = False
        self._thread: Optional[threading.Thread] = None

    # ─────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ─────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running:
            return True
        self._running = True

        # Demarrer HTTP /metrics
        start_http_server(self.cfg.port, registry=self.prom_reg)
        host = socket.gethostname()
        self.logger.info(f"Prometheus endpoint available at http://{host}:{self.cfg.port}/metrics")

        # Enregistrement NexusCore
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock"],
        )

        # Tick souscription
        clk = self.nexus.get_module("cognitive_clock")
        if clk:
            clk.subscribe(self.cfg.tick_channel, self._on_tick)

        # Boucle OTEL (optionnelle)
        if self.cfg.otel_enabled:
            self._thread = threading.Thread(target=self._otel_loop, daemon=True)
            self._thread.start()

        return True

    def stop(self):
        self._running = False
        return True

    # ─────────────────────────────────────────────────────────────────────
    # Prometheus scrape
    # ─────────────────────────────────────────────────────────────────────
    def _on_tick(self, _payload):
        start = time.perf_counter()
        try:
            self._scrape_metrics()
        except Exception as exc:
            self.c_scrape_errors.inc()
            self.logger.error(f"Metrics scrape error: {exc}")
        finally:
            self.s_scrape_latency.observe(time.perf_counter() - start)

    def _scrape_metrics(self):
        modules = self.nexus.list_modules()
        self.g_queue_size.set(len(self.nexus.message_queue))

        # Refresh gauges
        for mod in modules:
            self.g_module_up.labels(mod).set(1)
            health = 1.0
            inst = self.nexus.get_module(mod)
            if hasattr(inst, "health_check"):
                try:
                    h = inst.health_check()
                    health = 1.0 if h.get("healthy", True) else 0.0
                    # If ratio exists, prefer it
                    if "miss_ratio" in h:
                        health = 1.0 - h["miss_ratio"]
                except Exception:
                    health = 0.0
            self.g_module_health.labels(mod).set(health)

    # ─────────────────────────────────────────────────────────────────────
    # OpenTelemetry exporter
    # ─────────────────────────────────────────────────────────────────────
    def _init_otel(self):
        reader = None
        if self.cfg.otel_export_console:
            reader = PeriodicExportingMetricReader(ConsoleMetricExporter(), export_interval_millis=int(self.cfg.otel_interval * 1000))
        metrics.set_meter_provider(MeterProvider(metric_readers=[reader] if reader else []))
        self._meter = metrics.get_meter("grandnexus_metrics")
        self._otel_queue_gauge = self._meter.create_observable_gauge(
            name="gnx.core.queue.size",
            callbacks=[lambda opts: [metrics.Observation(len(self.nexus.message_queue))]],
        )
        self.logger.info("OpenTelemetry metrics initialised")

    def _otel_loop(self):
        # OTEL handled by PeriodicExportingMetricReader; just keep thread alive
        while self._running:
            time.sleep(1.0)

    # ─────────────────────────────────────────────────────────────────────
    # Health & status
    # ─────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        return {"prometheus_port": self.cfg.port, "otel": self.cfg.otel_enabled, "healthy": True}

    def get_status(self) -> Dict[str, Any]:
        return {"otel_enabled": self.cfg.otel_enabled}

