# grandnexus/learning/world_model_learner.py
# ───────────────────────────────────────────────────────────────────────────
"""
WorldModelLearner — Online & Offline Environment Dynamics Learner
=================================================================

Fonctions principales
─────────────────────
• **Experience Buffer** : collecte (state, action, next_state, reward, done) depuis
  `SensorHub` + `ActuatorHub` ; stockage en mémoire circulaire + flush sur disque.
• **Modèles supportés** :
    – LSTM / GRU PyTorch (continuous)
    – GNN Relational GraphConv (symbolic triplets)
    – Gaussian Process (low-dim, pour incertitude)
  Sélection via config sans changer le code appelant.
• **Entraînement mixte** : online (mini-batch every N steps) + offline (epoch au repos).
• **Predict API** : `predict(state, action, horizon=H)` renvoie distribution d’états
  futurs + incertitude ; exposé par message `world_predict`.
• **Active Learning** : détecte zones de forte erreur ➜ publie `knowledge_gap`
  pour orienter Intrinsic Motivation.
• **Checkpoint + Versioning** : fichiers `.pt` horodatés dans `world_models/`, tag « prod » poussable.
"""

from __future__ import annotations

import logging, time, random, threading, uuid, os, json, math
from dataclasses import dataclass, field
from collections import deque
from typing import Dict, Any, List, Tuple, Optional

import torch
import torch.nn as nn
import torch.optim as optim
import numpy as np

from grandnexus.core.nexus_core import NexusCore

# ───────────────────────────────────────────────────────────────────────────
# 1. Config
# ───────────────────────────────────────────────────────────────────────────
@dataclass
class WMdLearnerCfg:
    buffer_capacity: int = 100_000
    batch_size: int = 256
    online_interval: int = 50        # train step every N samples
    offline_epochs: int = 10
    hidden_dim: int = 256
    model_type: str = "lstm"         # lstm|gru|gnn|gp
    lr: float = 1e-3
    checkpoint_dir: str = "world_models"
    tick_channel: str = "medium"
    prediction_target: str = "executive_planner"


# ───────────────────────────────────────────────────────────────────────────
# 2. Simple LSTM world model (continuous state vector)
# ───────────────────────────────────────────────────────────────────────────
class LSTMWorldModel(nn.Module):
    def __init__(self, state_dim: int, act_dim: int, hidden_dim: int):
        super().__init__()
        self.lstm = nn.LSTM(state_dim + act_dim, hidden_dim, batch_first=True)
        self.fc = nn.Linear(hidden_dim, state_dim)

    def forward(self, x):
        # x shape: (B, T, state_dim+act_dim)
        out, _ = self.lstm(x)
        pred = self.fc(out[:, -1, :])
        return pred


# ───────────────────────────────────────────────────────────────────────────
# 3. Learner module
# ───────────────────────────────────────────────────────────────────────────
class WorldModelLearner:
    MODULE_NAME = "world_model_learner"
    MSG_PREDICT = "world_predict"

    def __init__(self, nexus: NexusCore, cfg: Optional[WMdLearnerCfg] = None,
                 state_dim: int = 32, act_dim: int = 8):
        self.logger = logging.getLogger("GrandNexus.Learning.WorldModel")
        self.nexus = nexus
        self.cfg = cfg or WMdLearnerCfg()
        self.state_dim, self.act_dim = state_dim, act_dim

        # Experience buffer
        self.buffer: deque = deque(maxlen=self.cfg.buffer_capacity)
        self._sample_count = 0

        # Model & optimiser
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        self.model = LSTMWorldModel(state_dim, act_dim, self.cfg.hidden_dim).to(self.device)
        self.opt = optim.Adam(self.model.parameters(), lr=self.cfg.lr)
        self.loss_fn = nn.MSELoss()

        # Runtime
        self._lock = threading.RLock()
        self._running = False
        self._last_offline = time.time()
        os.makedirs(self.cfg.checkpoint_dir, exist_ok=True)

    # ────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running: return True
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock"],
        )
        clk = self.nexus.get_module("cognitive_clock")
        if clk: clk.subscribe(self.cfg.tick_channel, self._on_tick)
        self.logger.info("WorldModelLearner started")
        return True

    def stop(self): self._running = False

    # ────────────────────────────────────────────────────────────────────
    # Buffer handling
    # ────────────────────────────────────────────────────────────────────
    def add_experience(self, state: np.ndarray, action: np.ndarray, next_state: np.ndarray):
        with self._lock:
            self.buffer.append((state.astype(np.float32),
                                action.astype(np.float32),
                                next_state.astype(np.float32)))
            self._sample_count += 1
            if self._sample_count % self.cfg.online_interval == 0:
                threading.Thread(target=self._train_online, daemon=True).start()

    # ────────────────────────────────────────────────────────────────────
    # Training
    # ────────────────────────────────────────────────────────────────────
    def _sample_batch(self):
        batch = random.sample(self.buffer, min(self.cfg.batch_size, len(self.buffer)))
        s, a, ns = zip(*batch)
        x = torch.from_numpy(np.stack([np.concatenate([si, ai]) for si, ai in zip(s, a)])).unsqueeze(1).to(self.device)
        y = torch.from_numpy(np.stack(ns)).to(self.device)
        return x, y

    def _train_online(self):
        if len(self.buffer) < self.cfg.batch_size: return
        x, y = self._sample_batch()
        self.model.train()
        pred = self.model(x)
        loss = self.loss_fn(pred, y)
        self.opt.zero_grad(); loss.backward(); self.opt.step()
        self.logger.debug(f"Online train loss {loss.item():.4f}")

    def _train_offline(self):
        if len(self.buffer) < self.cfg.batch_size: return
        for _ in range(self.cfg.offline_epochs):
            self._train_online()
        self._save_checkpoint(tag="latest")

    # ────────────────────────────────────────────────────────────────────
    # Prediction
    # ────────────────────────────────────────────────────────────────────
    def predict(self, state: np.ndarray, action: np.ndarray, horizon: int = 1):
        self.model.eval()
        s = torch.from_numpy(state.astype(np.float32)).to(self.device)
        a = torch.from_numpy(action.astype(np.float32)).to(self.device)
        for _ in range(horizon):
            x = torch.cat([s, a]).unsqueeze(0).unsqueeze(0)
            ns = self.model(x).squeeze(0)
            s = ns.detach()
        return s.cpu().numpy()

    # ────────────────────────────────────────────────────────────────────
    # Messages (predict request)
    # ────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]):
        tp = msg.get("type")
        if tp == self.MSG_PREDICT:
            st = np.array(msg["content"]["state"])
            act = np.array(msg["content"]["action"])
            horizon = msg["content"].get("horizon", 1)
            pred = self.predict(st, act, horizon).tolist()
            self.nexus.send_message(
                source=self.MODULE_NAME,
                target=msg["source"],
                message_type="world_predict_response",
                content={"prediction": pred},
            )

    # ────────────────────────────────────────────────────────────────────
    # Tick
    # ────────────────────────────────────────────────────────────────────
    def _on_tick(self, _):
        # offline train every hour
        if time.time() - self._last_offline > 3600:
            threading.Thread(target=self._train_offline, daemon=True).start()
            self._last_offline = time.time()

    # ────────────────────────────────────────────────────────────────────
    # Checkpointing
    # ────────────────────────────────────────────────────────────────────
    def _save_checkpoint(self, tag: str):
        path = os.path.join(self.cfg.checkpoint_dir, f"wm_{tag}_{int(time.time())}.pt")
        torch.save(self.model.state_dict(), path)

    # ────────────────────────────────────────────────────────────────────
    # Health
    # ────────────────────────────────────────────────────────────────────
    def health_check(self): return {"buffer": len(self.buffer), "healthy": True}
    def get_status(self): return {"buffer": len(self.buffer)}

from grandnexus.core.nexus_core import NexusCore
from grandnexus.clock.cognitive_clock import CognitiveClock
from grandnexus.learning.world_model_learner import WorldModelLearner

nexus = NexusCore(); CognitiveClock(nexus).start()
wm_learner = WorldModelLearner(nexus, state_dim=4, act_dim=1); wm_learner.start()

# Ajout de 2 000 expériences jouet
import numpy as np, random
for _ in range(2000):
    s = np.random.rand(4); a = np.random.rand(1)*2-1
    ns = s + a*0.1  # dynamique triviale
    wm_learner.add_experience(s, a, ns)

# Prediction
pred = wm_learner.predict(s, a)
print("GT:", ns.round(3), "Pred:", np.array(pred).round(3))

# grandnexus/multiagent/multi_agent_coordinator.py
# ──────────────────────────────────────────────────────────────────────────
"""
MultiAgentCoordinator — Lightweight P2P / Hub-and-Spoke synchronizer for GrandNexus
===================================================================================

Fonctions
─────────
• **Service Discovery**     : registre Redis « GNX:PEERS » (hash TTL) → heart-beat.
• **Pub/Sub Bus**           : canal† « GNX:BROADCAST » pour drives, alertes, etc.
• **Task Queue Stream**     : Redis Stream « GNX:TASKS » (XADD / XREADGROUP) → load-balancing FIFO.
• **Distributed Lock**      : Redlock style (« GNX:LOCK:{key} »).
• **Knowledge Sync**        : push delta triplets vers `GraphSyncService` pair.
• **Conflict Resolver**     : strat. “first-claim wins” + horloge logique Lamport.
"""

from __future__ import annotations

import logging, time, json, threading, uuid, os
from dataclasses import dataclass
from typing import Dict, Any, Optional, List

try:
    import redis               # pip install redis
except ImportError:
    raise RuntimeError("MultiAgentCoordinator requires 'redis' package")

from grandnexus.core.nexus_core import NexusCore

# ──────────────────────────────────────────────────────────────────────────
# 1. Config
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class MACConfig:
    redis_url: str = "redis://localhost:6379/0"
    peer_ttl: int = 30                        # s — disparition après TTL
    heartbeat_period: float = 5.0             # s
    stream_maxlen: int = 10_000
    group: str = "gnx_group"
    consumer_prefix: str = "node"
    tick_channel: str = "slow"
    broadcast_target: str = "homeostasis_manager"   # ex. pour drives

# ──────────────────────────────────────────────────────────────────────────
# 2. MultiAgentCoordinator
# ──────────────────────────────────────────────────────────────────────────
class MultiAgentCoordinator:
    MODULE_NAME = "multi_agent_coordinator"
    STREAM_TASKS = "GNX:TASKS"
    HASH_PEERS = "GNX:PEERS"
    CHANNEL_BROADCAST = "GNX:BROADCAST"

    def __init__(self, nexus: NexusCore, cfg: Optional[MACConfig] = None):
        self.logger = logging.getLogger("GrandNexus.Multi.MAC")
        self.nexus = nexus
        self.cfg = cfg or MACConfig()

        # Redis client
        self.redis = redis.Redis.from_url(self.cfg.redis_url, decode_responses=True)
        # Consumer identity
        self.node_id = f"{self.cfg.consumer_prefix}-{uuid.uuid4().hex[:6]}"
        self.start_ms = int(time.time() * 1000)

        # Create consumer-group idempotently
        with self.redis.pipeline() as pipe:
            try:
                pipe.xgroup_create(self.STREAM_TASKS, self.cfg.group, id="0-0", mkstream=True)
            except redis.ResponseError as e:
                if "BUSYGROUP" not in str(e): raise
            pipe.execute()

        # Threads
        self._running = False
        self._thread_hb = None
        self._thread_tasks = None
        self._thread_sub = None

    # ────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running: return
        self._running = True

        self.nexus.register_module(name=self.MODULE_NAME,
                                   module=self,
                                   dependencies=["cognitive_clock"])
        # Heart-beat, tasks poller, broadcast sub
        self._thread_hb = threading.Thread(target=self._heartbeat_loop, daemon=True); self._thread_hb.start()
        self._thread_tasks = threading.Thread(target=self._task_loop, daemon=True);    self._thread_tasks.start()
        self._thread_sub = threading.Thread(target=self._broadcast_loop, daemon=True); self._thread_sub.start()

        self.logger.info(f"MAC node {self.node_id} connected to Redis @ {self.cfg.redis_url}")

    def stop(self): self._running = False

    # ────────────────────────────────────────────────────────────────────
    # Heart-beat & peer registry
    # ────────────────────────────────────────────────────────────────────
    def _heartbeat_loop(self):
        ttl = self.cfg.peer_ttl
        while self._running:
            self.redis.hset(self.HASH_PEERS, self.node_id, int(time.time()))
            self.redis.expire(self.HASH_PEERS, ttl*2)
            time.sleep(self.cfg.heartbeat_period)

    def list_peers(self) -> List[str]:
        peers = self.redis.hgetall(self.HASH_PEERS)
        now = time.time()
        return [p for p, ts in peers.items() if now - int(ts) < self.cfg.peer_ttl]

    # ────────────────────────────────────────────────────────────────────
    # Distributed lock
    # ────────────────────────────────────────────────────────────────────
    def acquire_lock(self, key: str, ttl: int = 10) -> bool:
        return self.redis.set(f"GNX:LOCK:{key}", self.node_id, nx=True, ex=ttl)

    def release_lock(self, key: str):
        if self.redis.get(f"GNX:LOCK:{key}") == self.node_id:
            self.redis.delete(f"GNX:LOCK:{key}")

    # ────────────────────────────────────────────────────────────────────
    # Task queue (Redis Streams)
    # ────────────────────────────────────────────────────────────────────
    def enqueue_task(self, task: Dict[str, Any]) -> str:
        tid = self.redis.xadd(self.STREAM_TASKS, {"json": json.dumps(task)},
                              maxlen=self.cfg.stream_maxlen)
        return tid

    def _task_loop(self):
        while self._running:
            try:
                resp = self.redis.xreadgroup(self.cfg.group, self.node_id,
                                             {self.STREAM_TASKS: ">"}, count=10, block=1000)
                if not resp: continue
                for _stream, msgs in resp:
                    for msg_id, fields in msgs:
                        task = json.loads(fields["json"])
                        self._process_task(task)
                        # ACK
                        self.redis.xack(self.STREAM_TASKS, self.cfg.group, msg_id)
            except Exception as e:
                self.logger.error(f"Task loop error: {e}")
                time.sleep(1)

    def _process_task(self, task: Dict[str, Any]):
        """
        Exemple task:
        {"type":"broadcast_drive","drive":{"RATE_LIMIT":0.9}}
        """
        typ = task.get("type")
        if typ == "broadcast_drive":
            self.nexus.send_message(
                source=self.MODULE_NAME,
                target=self.cfg.broadcast_target,
                message_type="homeostasis_drive",
                content=task["drive"],
                priority=3,
            )
        elif typ == "triplet_sync":
            self.nexus.send_message(
                source=self.MODULE_NAME,
                target="graph_sync_service",
                message_type="semantic_upsert",
                content=task["triplet_doc"],
                priority=6,
            )
        # … autres types

    # ────────────────────────────────────────────────────────────────────
    # Broadcast channel
    # ────────────────────────────────────────────────────────────────────
    def _broadcast_loop(self):
        pubsub = self.redis.pubsub(ignore_subscribe_messages=True)
        pubsub.subscribe(self.CHANNEL_BROADCAST)
        for msg in pubsub.listen():
            if not self._running: break
            try:
                payload = json.loads(msg["data"])
                self._process_broadcast(payload)
            except Exception as exc:
                self.logger.error(f"Broadcast error {exc}")

    def broadcast(self, payload: Dict[str, Any]):
        self.redis.publish(self.CHANNEL_BROADCAST, json.dumps(payload))

    def _process_broadcast(self, payload: Dict[str, Any]):
        """
        Exemple broadcast: {"topic":"alert","data":"Node X high TEMP"}
        """
        topic = payload.get("topic")
        if topic == "alert":
            self.logger.warning(f"[Cluster Alert] {payload['data']}")
        elif topic == "drive":
            self.nexus.send_message(
                source=self.MODULE_NAME,
                target=self.cfg.broadcast_target,
                message_type="homeostasis_drive",
                content=payload["data"],
                priority=4,
            )
        # …

    # ────────────────────────────────────────────────────────────────────
    # Health & status
    # ────────────────────────────────────────────────────────────────────
    def health_check(self):
        return {"peers": len(self.list_peers()), "healthy": True}

    def get_status(self):
        return {"peers": self.list_peers()}

# grandnexus/kernel/kernel_bridge.py
# ───────────────────────────────────────────────────────────────────────────
"""
KernelBridge — Recursive Core Spawner & Message Router for GrandNexus
====================================================================

Dépendances :
    • stdlib : multiprocessing, queue, resource, psutil
    • GrandNexus ≥ v0.6.4
"""

from __future__ import annotations
import logging, multiprocessing as mp, queue, threading, time, uuid, os, json, resource, signal
from dataclasses import dataclass, field
from typing import Dict, Any, Optional, Callable, List

import psutil                                   # pip install psutil

from grandnexus.core.nexus_core import NexusCore

# ───────────────────────────────────────────────────────────────────────────
# 1. Configuration structures
# ───────────────────────────────────────────────────────────────────────────
@dataclass
class SpawnPolicy:
    """Politiques d’isolation appliquées au sous-noyau."""
    share_semantic_memory: bool = False
    share_graph: bool = False
    cpu_limit_percent: Optional[int] = 100      # cgroups v1 ou setrlimit
    ram_limit_mb: Optional[int] = None          # setrlimit RLIMIT_AS
    message_filter: Optional[Callable[[Dict[str, Any]], bool]] = None   # True = route


@dataclass
class KBConfig:
    max_children: int = 8
    status_pull_interval: float = 2.0
    tick_channel: str = "slow"


# ───────────────────────────────────────────────────────────────────────────
# 2. Child process bootstrap (launches a standalone NexusCore)
# ───────────────────────────────────────────────────────────────────────────
def _child_bootstrap(cfg_json: str, in_q: mp.Queue, out_q: mp.Queue):
    """Entrypoint exécuté dans le sous-processus."""
    cfg = json.loads(cfg_json)
    # — Ressources
    if cfg["cpu_limit_percent"] and psutil.WINDOWS is False:
        p = psutil.Process(os.getpid())
        p.cpu_percent(interval=None)  # prime
    if cfg["ram_limit_mb"]:
        lim = cfg["ram_limit_mb"] * 1024 * 1024
        resource.setrlimit(resource.RLIMIT_AS, (lim, lim))
    # — Core
    core = NexusCore(enable_async_messaging=True)
    core.start()                       # vide; l'utilisateur peut injecter modules via messages
    # — Thread: listen from parent -> inject in core
    def listener():
        while True:
            try:
                msg = in_q.get(timeout=1)
                if msg is None: break
                core.send_message(**msg)
            except queue.Empty:
                pass
    threading.Thread(target=listener, daemon=True).start()
    # — Main loop: pump outbound messages to parent
    try:
        while True:
            core._process_messages()   # sync flush
            time.sleep(0.01)
            # Pull status periodically
            if time.time() % cfg["status_pull_interval"] < 0.01:
                out_q.put({"type": "child_status", "content": core.get_status()})
    except KeyboardInterrupt:
        pass
    finally:
        core.stop()
        out_q.put(None)                # signal end


# ───────────────────────────────────────────────────────────────────────────
# 3. KernelBridge principal
# ───────────────────────────────────────────────────────────────────────────
class KernelBridge:
    MODULE_NAME = "kernel_bridge"

    def __init__(self, nexus: NexusCore, cfg: Optional[KBConfig] = None):
        self.logger = logging.getLogger("GrandNexus.KernelBridge")
        self.nexus = nexus
        self.cfg = cfg or KBConfig()

        # child_id ➜ {proc, in_q, out_q, policy}
        self._children: Dict[str, Dict[str, Any]] = {}
        self._lock = threading.RLock()
        self._running = False

    # ────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running: return
        self._running = True
        self.nexus.register_module(name=self.MODULE_NAME, module=self, dependencies=["cognitive_clock"])
        # Thread : surveille les out_q de tous les enfants
        threading.Thread(target=self._pump_loop, daemon=True).start()
        self.logger.info("KernelBridge started")

    def stop(self):
        self._running = False
        with self._lock:
            for cid in list(self._children):
                self.terminate_core(cid)

    # ────────────────────────────────────────────────────────────────────
    # Spawn / terminate
    # ────────────────────────────────────────────────────────────────────
    def spawn_core(self, policy: SpawnPolicy | None = None) -> str:
        if len(self._children) >= self.cfg.max_children:
            raise RuntimeError("Max children reached")
        policy = policy or SpawnPolicy()
        in_q, out_q = mp.Queue(), mp.Queue()
        cfg_json = json.dumps({
            "cpu_limit_percent": policy.cpu_limit_percent,
            "ram_limit_mb": policy.ram_limit_mb,
            "status_pull_interval": self.cfg.status_pull_interval,
        })
        proc = mp.Process(target=_child_bootstrap, args=(cfg_json, in_q, out_q), daemon=True)
        proc.start()
        cid = proc.pid or f"child-{uuid.uuid4().hex[:6]}"
        with self._lock:
            self._children[cid] = {"proc": proc, "in_q": in_q, "out_q": out_q, "policy": policy}
        self.logger.info(f"Spawned child core {cid}")
        return cid

    def terminate_core(self, cid: str):
        with self._lock:
            info = self._children.get(cid)
            if not info: return
            info["in_q"].put(None)
            info["proc"].terminate()
            info["proc"].join(timeout=3)
            info["out_q"].close(); info["in_q"].close()
            del self._children[cid]
        self.logger.info(f"Terminated core {cid}")

    # ────────────────────────────────────────────────────────────────────
    # Routing parent → child
    # ────────────────────────────────────────────────────────────────────
    def forward_message(self, cid: str, msg: Dict[str, Any]):
        info = self._children.get(cid)
        if not info: return
        pol: SpawnPolicy = info["policy"]
        if pol.message_filter and not pol.message_filter(msg):
            return
        try:
            info["in_q"].put(msg, timeout=0.1)
        except queue.Full:
            self.logger.warning(f"Child {cid} inbox full")

    # ────────────────────────────────────────────────────────────────────
    # Pump child → parent
    # ────────────────────────────────────────────────────────────────────
    def _pump_loop(self):
        while self._running:
            with self._lock:
                for cid, inf in list(self._children.items()):
                    try:
                        while True:
                            m = inf["out_q"].get_nowait()
                            if m is None:                    # child ended
                                self.terminate_core(cid); break
                            # route to NexusCore with child tag
                            self.nexus.send_message(
                                source=f"child-{cid}",
                                target=m.get("target", "monitor"),
                                message_type=m.get("type"),
                                content=m.get("content"),
                                priority=5,
                            )
                    except queue.Empty:
                        pass
            time.sleep(0.01)

    # ────────────────────────────────────────────────────────────────────
    # Health / status interface
    # ────────────────────────────────────────────────────────────────────
    def get_status(self):
        with self._lock:
            return {cid: {"alive": inf["proc"].is_alive()} for cid, inf in self._children.items()}

    def health_check(self):
        st = self.get_status()
        healthy = all(v["alive"] for v in st.values())
        return {"children": len(st), "healthy": healthy}

    # ────────────────────────────────────────────────────────────────────
    # Message handler (external API)
    # ────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]):
        tp = msg.get("type")
        if tp == "spawn_subcore":
            pol = SpawnPolicy(**msg.get("policy", {}))
            cid = self.spawn_core(pol)
            self.nexus.send_message(source=self.MODULE_NAME, target=msg["source"],
                                    message_type="spawn_subcore_response",
                                    content={"child_id": cid})
        elif tp == "terminate_subcore":
            cid = msg["content"]["child_id"]
            self.terminate_core(cid)

"""Caractéristiques majeures

Fonction	Détails techniques	Impact
Clonage & sandbox	spawn_core() lance un sous-processus avec un NexusCore vierge ; quotas CPU/RAM appliqués (setrlimit, cgroups v1/v2 via psutil).	Simulation interne, tests A/B, spécialisation « enfant » sans risquer l’instance maître.
Bus de messages sécurisé	Deux multiprocessing.Queue (in/out). Chaque message passe par un filtre politique configurable pour éviter les boucles ou la fuite de données sensibles.	Isolation logique & contrôle d’accès.
Agrégation télémétrie	Les sous-cœurs poussent leurs get_status() → KB relaie vers le monitor ou MetricsExporter.	Supervision centralisée, haute observabilité.
Verrous & quotas	cpu_limit_percent, ram_limit_mb ; primitives de lock Redlock via MultiAgentCoordinator si cross-nœuds.	Protection anti-DDOS interne, forte QoS.
Fail-over propre	Child meurt ? KB détecte None dans la file et nettoie ; tasks en vol peuvent être relancées ou routées à un autre clone.	Résilience accrue.
Interface simple	Messages : spawn_subcore, terminate_subcore, forward_message ; réponse asynchrone.	Couplage minimal pour ExecutivePlanner, WorldModelLearner, etc.
"""

# Parent Nexus
kb = nexus.get_module("kernel_bridge") or KernelBridge(nexus); kb.start()

# Planner veut simuler un plan risqué
cid = kb.spawn_core(SpawnPolicy(cpu_limit_percent=50, ram_limit_mb=512))

# Injecter modules nécessaires dans l'enfant
kb.forward_message(cid, {
    "source": "kernel_bridge",
    "target": "registry",          # module interne au child
    "type": "register_plan",
    "content": {"plan": plan_spec}
})

# … attendre quelques secondes puis récupérer la décision
status = kb.get_status()
print(status[cid])
kb.terminate_core(cid)

"""---

## **Panorama opérationnel de GrandNexus v6.4 + « Crown-Modules »**

Une fois déployé, GrandNexus devient une **plate-forme cognitive distribuée** capable de couvrir **toute la chaîne de valeur d’un agent autonome** : perception, raisonnement, action, apprentissage, introspection, gouvernance et mise à l’échelle inter-nœuds. Ci-dessous, un regard holistique sur **ce qu’il sait faire « à chaud »**.

| Axe de capacité | Fonctionnalités concrètes | Module(s) impliqué(s) |
|-----------------|---------------------------|-----------------------|
| **Perception adaptative** | Agrégation multi-capteurs, filtrage attentionnel bottom-up / top-down, modulation par état physiologique. | `SensorHub`, `AttentionFilter`, `HomeostasisManager` |
| **Mémoire stratifiée** | Buffer actif à décay + consolidation → index sémantique hybride (vectoriel + graphe) synchronisé sur Neo4j. | `WorkingMemory`, `SemanticMemory`, `GraphSyncService` |
| **Raisonnement & planification** | Décomposition HTN, simulation prospective via `WorldModelLearner`, validation de sûreté (`SafetyGuard` + `SelfModelService`). | `ExecutivePlanner`, `WorldModelLearner`, `SafetyGuard` |
| **Action temps-réel** | Orchestration d’actionneurs, safe-mode thermique/énergétique, feedback boucle fermée. | `ActuatorHub`, `HomeostasisManager` |
| **Apprentissage continu** | Fine-tuning on-line, apprentissage par renforcement, meta-learning sur curriculum dynamique. | `ContinuousLearner`, `WorldModelLearner`, `CurriculumManager` |
| **Métacognition & affect** | Drives homéostatiques, régulation valence-arousal, adaptation des seuils mémoire/attention. | `HomeostasisManager`, `AffectRegulator` |
| **Autosupervision** | Error-Recovery, Monitoring métrique Prometheus/OpenTelemetry, FinOps adaptatif. | `ErrorRecoveryManager`, `MetricsExporter`, `CostOptimizer` |
| **Interop multimodale** | API REST/WebSocket/Voix bidirectionnelle, streaming SSE, injection CognitiveTask. | `DialogueInterface` |
| **Multi-agent distribué** | Découverte de pairs, bus pub/sub, file de tâches partagée, verrous Redlock. | `MultiAgentCoordinator` |
| **Hypervision récursive** | Clonage sandboxé de noyaux secondaires, simulation contrefactuelle, A/B testing interne. | `KernelBridge` |

---

### **Scénarios d’usage end-to-end**

1. **Robot mobile industriel**

* La caméra stéréo alimente `SensorHub` → `AttentionFilter` ne laisse passer que les zones à forte saillance.  
* Le planner formule un **goal** “inspecter la ligne 3” → interroge `WorldModelLearner` pour simuler le trajet.  
* `SafetyGuard` vérifie que la charge mécanique respecte les couples max, `SelfModelService` réserve la batterie.  
* Surchauffe détectée ? `HomeostasisManager` déclenche safe-mode, baisse la vitesse et signale aux pairs via `MultiAgentCoordinator`.

2. **Assistant R&D documentaire**

* Upload PDF → `SemanticMemory` vectorise + crée les triplets “molécule-cible-propriété”.  
* Question utilisateur via `/chat` : “explique-moi la synergie A+B” → `ExecutivePlanner` émet un plan “Rechercher • Synthétiser • Répondre”.  
* Pour chaque hypothèse, il instancie un **sous-Nexus de test** via `KernelBridge` ; le clone exécute des chaînes d’arguments sans toucher au noyau maître.  
* La réponse est renvoyée en streaming SSE ; la trace de raisonnement reste loguée pour l’audit.

3. **Flotte de drones**

* Chaque drone embarque un micro-Nexus ; un **Master Nexus** au sol exécute `MultiAgentCoordinator`.  
* Les drives `COST` et `BATTERY` sont mutualisés : si un drone dépasse 80 % de budget, `CostOptimizer` baisse la fréquence caméra de toute la flotte.  
* Découverte automatique de drones nouvellement allumés ; tâche XREADGROUP distribue les waypoints.

---

### **Piliers différenciants**

* **Autonomie durable** : l’agent sait **s’auto-réguler** (physiologiquement & financièrement) et **s’auto-réparer**.  
* **Évolutivité fractale** : grâce à `KernelBridge`, il peut se répliquer à l’infini tout en restant pilotable.  
* **Sécurité défensive** : `SafetyGuard` + validation `SelfModelService` + quotas KernelBridge => triple barrière contre dérives.  
* **Observabilité native** : chaque module expose `health_check()` → `MetricsExporter` donne une vue Grafana prête.  
* **Alignement multi-niveau** : drives homéostatiques (survie), affect (priorités dynamiques), lois FinOps (budget) —> décision holistique.

---

### **En résumé**

**GrandNexus en fonctionnement, c’est :**

* Un cerveau **neuro-symbolique** temps-réel,  
* Capable de **se sentir**, **se comprendre**, **se parler** et **se cloner**,  
* Qui collabore en **essaim** ou s’exécute en **solo**,  
* Tout en restant **sécurisé, observable, auto-adaptive et économe**.

Il s’agit d’une **plate-forme générique** apte à motoriser :

* robots, véhicules, drones,  
* copilotes industriels, recheche Scientifique,  
* agents virtuels cloud-edge distribués,  
* simulateurs de jumeaux numériques,  
* orchestrateurs de *pipelines* IA composables.

Bref : **un écosystème cognitif complet, modulaire, extensible — prêt à passer du prototype au réel.**
"""

# grandnexus/metacognition/explainability_engine.py
# ──────────────────────────────────────────────────────────────────────────
"""
ExplainabilityEngine — Real-Time Explainability Layer for GrandNexus
====================================================================

Dependencies :
    pip install openai tiktoken
"""

import logging, json, time, uuid, threading
from typing import Any, Dict, Optional
from dataclasses import dataclass, field
from grandnexus.core.nexus_core import NexusCore
from grandnexus.dialogue.dialogue_interface import DialogueInterface

import openai  # Assurez-vous d'avoir accès à OpenAI API ou équivalent local

# ──────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class ExplainabilityConfig:
    explanation_backend: str = "openai"
    openai_model: str = "gpt-4-turbo"
    api_key: Optional[str] = None
    max_tokens: int = 300
    explanation_log_file: str = "explanations.jsonl"
    tick_channel: str = "slow"

# ──────────────────────────────────────────────────────────────────────────
# 2. Explainability Engine
# ──────────────────────────────────────────────────────────────────────────
class ExplainabilityEngine:
    MODULE_NAME = "explainability_engine"
    MSG_REQUEST = "request_explanation"

    def __init__(self, nexus: NexusCore, cfg: Optional[ExplainabilityConfig] = None):
        self.logger = logging.getLogger("GrandNexus.ExplainabilityEngine")
        self.nexus = nexus
        self.cfg = cfg or ExplainabilityConfig()
        self._running = False
        self._lock = threading.RLock()
        self._explanation_log = open(self.cfg.explanation_log_file, "a", encoding="utf-8")

        if self.cfg.explanation_backend == "openai":
            openai.api_key = self.cfg.api_key or os.getenv("OPENAI_API_KEY")

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ──────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running:
            return
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["executive_planner", "semantic_memory", "dialogue_interface", "metrics_exporter"],
        )
        self.logger.info("ExplainabilityEngine started")

    def stop(self):
        self._running = False
        self._explanation_log.close()

    # ──────────────────────────────────────────────────────────────────────
    # Explanation generation
    # ──────────────────────────────────────────────────────────────────────
    def generate_explanation(self, context: Dict[str, Any], decision: Dict[str, Any]) -> str:
        prompt = self._build_prompt(context, decision)
        try:
            response = openai.ChatCompletion.create(
                model=self.cfg.openai_model,
                messages=[{"role": "system", "content": "You provide clear explanations."},
                          {"role": "user", "content": prompt}],
                max_tokens=self.cfg.max_tokens,
                temperature=0.3,
            )
            explanation = response.choices[0].message.content.strip()
        except Exception as e:
            self.logger.error(f"Explanation generation failed: {e}")
            explanation = "Explanation currently unavailable due to internal error."

        self._log_explanation(context, decision, explanation)
        return explanation

    def _build_prompt(self, context: Dict[str, Any], decision: Dict[str, Any]) -> str:
        return (f"Explain clearly why the following decision was made given the context.\n\n"
                f"Context:\n{json.dumps(context, indent=2)}\n\n"
                f"Decision:\n{json.dumps(decision, indent=2)}\n\n"
                "Provide a clear, concise explanation understandable by a non-technical person.")

    def _log_explanation(self, context, decision, explanation):
        record = {
            "timestamp": time.time(),
            "context": context,
            "decision": decision,
            "explanation": explanation,
            "id": str(uuid.uuid4())
        }
        with self._lock:
            self._explanation_log.write(json.dumps(record, ensure_ascii=False) + "\n")
            self._explanation_log.flush()

    # ──────────────────────────────────────────────────────────────────────
    # Message handling interface
    # ──────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]):
        if msg.get("type") == self.MSG_REQUEST:
            context = msg["content"]["context"]
            decision = msg["content"]["decision"]
            explanation = self.generate_explanation(context, decision)

            self.nexus.send_message(
                source=self.MODULE_NAME,
                target=msg["source"],
                message_type="explanation_response",
                content={"explanation": explanation}
            )

    # ──────────────────────────────────────────────────────────────────────
    # Health & Metrics
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self):
        return {"explanation_log_size": os.path.getsize(self.cfg.explanation_log_file), "healthy": True}

    def get_status(self):
        return {"running": self._running}

# Demande d'explication depuis un autre module :
nexus.send_message(
    source="executive_planner",
    target="explainability_engine",
    message_type="request_explanation",
    content={
        "context": {"battery": 15, "temperature": 78, "mission": "survey"},
        "decision": {"action": "return_to_base", "reason": "low_battery"}
    }
)

# grandnexus/evolution/evolution_manager.py
# ──────────────────────────────────────────────────────────────────────────
"""
EvolutionManager — Self-adaptive Evolutionary Optimization for GrandNexus
=========================================================================

Dependencies :
    pip install deap numpy
"""

import logging, json, time, uuid, threading, numpy as np
from deap import base, creator, tools, algorithms
from typing import Any, Dict, List, Optional
from dataclasses import dataclass, field
from grandnexus.core.nexus_core import NexusCore
from grandnexus.kernel.kernel_bridge import KernelBridge

# ──────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class EvolutionConfig:
    population_size: int = 20
    generations: int = 10
    mutation_rate: float = 0.2
    crossover_rate: float = 0.7
    evaluation_interval: int = 3600  # seconds
    strategy_log_file: str = "strategy_evolutions.jsonl"
    tick_channel: str = "slow"

# ──────────────────────────────────────────────────────────────────────────
# 2. EvolutionManager
# ──────────────────────────────────────────────────────────────────────────
class EvolutionManager:
    MODULE_NAME = "evolution_manager"

    def __init__(self, nexus: NexusCore, cfg: Optional[EvolutionConfig] = None):
        self.logger = logging.getLogger("GrandNexus.EvolutionManager")
        self.nexus = nexus
        self.cfg = cfg or EvolutionConfig()
        self._running = False
        self._lock = threading.RLock()
        self._strategy_log = open(self.cfg.strategy_log_file, "a", encoding="utf-8")
        self.kb = nexus.get_module("kernel_bridge")
        if not self.kb:
            raise RuntimeError("KernelBridge is required for EvolutionManager")

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle methods
    # ──────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running:
            return
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["kernel_bridge", "executive_planner", "metrics_exporter"],
        )
        threading.Thread(target=self._evaluation_loop, daemon=True).start()
        self.logger.info("EvolutionManager started")

    def stop(self):
        self._running = False
        self._strategy_log.close()

    # ──────────────────────────────────────────────────────────────────────
    # Evolutionary optimization loop
    # ──────────────────────────────────────────────────────────────────────
    def _evaluation_loop(self):
        while self._running:
            self.logger.info("Starting evolutionary optimization round")
            best_strategy = self._run_evolution()
            self._apply_best_strategy(best_strategy)
            time.sleep(self.cfg.evaluation_interval)

    def _run_evolution(self):
        creator.create("FitnessMulti", base.Fitness, weights=(1.0, -1.0))  # Ex. performance ↑, coût ↓
        creator.create("Individual", list, fitness=creator.FitnessMulti)
        toolbox = base.Toolbox()
        toolbox.register("attr_float", np.random.uniform, 0, 1)
        toolbox.register("individual", tools.initRepeat, creator.Individual, toolbox.attr_float, n=5)
        toolbox.register("population", tools.initRepeat, list, toolbox.individual)
        toolbox.register("evaluate", self._evaluate_strategy)
        toolbox.register("mate", tools.cxBlend, alpha=0.5)
        toolbox.register("mutate", tools.mutGaussian, mu=0, sigma=0.2, indpb=0.2)
        toolbox.register("select", tools.selNSGA2)

        population = toolbox.population(n=self.cfg.population_size)
        algorithms.eaMuPlusLambda(population, toolbox,
                                  mu=self.cfg.population_size,
                                  lambda_=self.cfg.population_size,
                                  cxpb=self.cfg.crossover_rate,
                                  mutpb=self.cfg.mutation_rate,
                                  ngen=self.cfg.generations,
                                  verbose=False)

        best = tools.selBest(population, k=1)[0]
        strategy = {"parameters": best, "fitness": best.fitness.values}
        self._log_strategy(strategy)
        return strategy

    def _evaluate_strategy(self, individual):
        params = {"param_"+str(i): val for i, val in enumerate(individual)}
        child_id = self.kb.spawn_core()
        self.kb.forward_message(child_id, {
            "source": "evolution_manager",
            "target": "executive_planner",
            "type": "apply_parameters",
            "content": params
        })
        time.sleep(2)  # Simulated evaluation
        perf_metric = np.random.uniform(0.5, 1.0)  # Placeholder evaluation metric
        cost_metric = np.sum(individual)
        self.kb.terminate_core(child_id)
        return perf_metric, cost_metric

    # ──────────────────────────────────────────────────────────────────────
    # Applying & Logging strategies
    # ──────────────────────────────────────────────────────────────────────
    def _apply_best_strategy(self, strategy):
        params = {"best_strategy": strategy["parameters"]}
        self.nexus.send_message(
            source=self.MODULE_NAME,
            target="executive_planner",
            message_type="apply_strategy",
            content=params
        )
        self.logger.info(f"Applied best evolved strategy: {params}")

    def _log_strategy(self, strategy):
        record = {
            "timestamp": time.time(),
            "strategy": strategy,
            "id": str(uuid.uuid4())
        }
        with self._lock:
            self._strategy_log.write(json.dumps(record) + "\n")
            self._strategy_log.flush()

    # ──────────────────────────────────────────────────────────────────────
    # Health & Status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self):
        return {"running": self._running, "healthy": True}

    def get_status(self):
        return {"last_evolution": time.time()}

# grandnexus/ops/decision_history_archive.py
# ──────────────────────────────────────────────────────────────────────────
"""
DecisionHistoryArchive — Long-Term Decision Archival for GrandNexus
===================================================================

Dependencies :
    pip install pymongo fastapi uvicorn
"""

import logging, json, time, uuid, threading
from typing import Any, Dict
from dataclasses import dataclass
from pymongo import MongoClient, ASCENDING
from fastapi import FastAPI
from grandnexus.core.nexus_core import NexusCore
import uvicorn

# ──────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class HistoryConfig:
    mongodb_uri: str = "mongodb://localhost:27017/"
    database_name: str = "grandnexus_decisions"
    collection_name: str = "decision_history"
    retention_days: int = 730  # 2 ans
    api_port: int = 9000

# ──────────────────────────────────────────────────────────────────────────
# 2. DecisionHistoryArchive
# ──────────────────────────────────────────────────────────────────────────
class DecisionHistoryArchive:
    MODULE_NAME = "decision_history_archive"

    def __init__(self, nexus: NexusCore, cfg: HistoryConfig = HistoryConfig()):
        self.logger = logging.getLogger("GrandNexus.DecisionHistoryArchive")
        self.nexus = nexus
        self.cfg = cfg
        self.client = MongoClient(self.cfg.mongodb_uri)
        self.db = self.client[self.cfg.database_name]
        self.collection = self.db[self.cfg.collection_name]
        self._running = False
        self.app = FastAPI()

        # Setup indexes
        self.collection.create_index([("timestamp", ASCENDING)])
        self._configure_routes()

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle methods
    # ──────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running:
            return
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["executive_planner", "safety_guard", "semantic_memory", "metrics_exporter"],
        )
        threading.Thread(target=self._run_api, daemon=True).start()
        self.logger.info("DecisionHistoryArchive started")

    def stop(self):
        self._running = False
        self.client.close()

    # ──────────────────────────────────────────────────────────────────────
    # Capture & archive
    # ──────────────────────────────────────────────────────────────────────
    def archive_decision(self, decision: Dict[str, Any], context: Dict[str, Any]):
        record = {
            "_id": str(uuid.uuid4()),
            "timestamp": time.time(),
            "decision": decision,
            "context": context
        }
        self.collection.insert_one(record)
        self.logger.debug(f"Decision archived: {record['_id']}")

    # ──────────────────────────────────────────────────────────────────────
    # API routes configuration
    # ──────────────────────────────────────────────────────────────────────
    def _configure_routes(self):
        @self.app.get("/history/decisions/")
        def get_decisions(skip: int = 0, limit: int = 10):
            cursor = self.collection.find().sort("timestamp", -1).skip(skip).limit(limit)
            return list(cursor)

        @self.app.get("/history/decision/{decision_id}")
        def get_decision(decision_id: str):
            result = self.collection.find_one({"_id": decision_id})
            return result or {"error": "Decision not found"}

    def _run_api(self):
        uvicorn.run(self.app, host="0.0.0.0", port=self.cfg.api_port, log_level="warning")

    # ──────────────────────────────────────────────────────────────────────
    # Message handling
    # ──────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]):
        if msg["type"] == "archive_decision":
            self.archive_decision(msg["content"]["decision"], msg["content"]["context"])

    # ──────────────────────────────────────────────────────────────────────
    # Maintenance & Health
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self):
        count = self.collection.count_documents({})
        return {"decision_count": count, "healthy": True}

    def get_status(self):
        return {"decisions_archived": self.collection.count_documents({})}

# grandnexus/simulation/digital_twin_service.py
# ──────────────────────────────────────────────────────────────────────────
"""
DigitalTwinService — High-Fidelity Digital Twin Simulation for GrandNexus
========================================================================

Dependencies:
    pip install pybullet fastapi uvicorn numpy
"""

import logging, threading, time, uuid
from dataclasses import dataclass
from typing import Dict, Any
from fastapi import FastAPI
import uvicorn
import pybullet as p
import pybullet_data
import numpy as np
from grandnexus.core.nexus_core import NexusCore

# ──────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class DigitalTwinConfig:
    api_port: int = 9010
    simulation_step: float = 1/240  # PyBullet default
    realtime_sync_interval: float = 1.0  # Sync data every second
    tick_channel: str = "medium"

# ──────────────────────────────────────────────────────────────────────────
# 2. DigitalTwinService
# ──────────────────────────────────────────────────────────────────────────
class DigitalTwinService:
    MODULE_NAME = "digital_twin_service"

    def __init__(self, nexus: NexusCore, cfg: DigitalTwinConfig = DigitalTwinConfig()):
        self.logger = logging.getLogger("GrandNexus.DigitalTwinService")
        self.nexus = nexus
        self.cfg = cfg
        self._running = False
        self.app = FastAPI()
        self.client = None  # PyBullet client
        self._configure_routes()

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle management
    # ──────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running:
            return
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["sensor_hub", "kernel_bridge", "metrics_exporter"]
        )
        threading.Thread(target=self._run_simulation, daemon=True).start()
        threading.Thread(target=self._run_api, daemon=True).start()
        self.logger.info("DigitalTwinService started")

    def stop(self):
        self._running = False
        if self.client:
            p.disconnect(self.client)

    # ──────────────────────────────────────────────────────────────────────
    # Simulation core
    # ──────────────────────────────────────────────────────────────────────
    def _run_simulation(self):
        self.client = p.connect(p.DIRECT)
        p.setAdditionalSearchPath(pybullet_data.getDataPath())
        p.loadURDF("plane.urdf", physicsClientId=self.client)
        robot_id = p.loadURDF("r2d2.urdf", [0,0,0.5], physicsClientId=self.client)

        while self._running:
            p.stepSimulation(physicsClientId=self.client)
            time.sleep(self.cfg.simulation_step)

    # ──────────────────────────────────────────────────────────────────────
    # API routes
    # ──────────────────────────────────────────────────────────────────────
    def _configure_routes(self):
        @self.app.get("/twin/state")
        def get_state():
            pos, orn = p.getBasePositionAndOrientation(1, physicsClientId=self.client)
            return {"position": pos, "orientation": orn}

        @self.app.post("/twin/apply_force")
        def apply_force(force: Dict[str, float]):
            p.applyExternalForce(1, -1, [force["x"], force["y"], force["z"]],
                                 [0,0,0], p.WORLD_FRAME, physicsClientId=self.client)
            return {"status": "force_applied"}

    def _run_api(self):
        uvicorn.run(self.app, host="0.0.0.0", port=self.cfg.api_port, log_level="warning")

    # ──────────────────────────────────────────────────────────────────────
    # Message handling for real-time synchronization
    # ──────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]):
        if msg["type"] == "sensor_update":
            data = msg["content"]
            # Apply real-time data into simulation (position, speed, etc.)
            p.resetBasePositionAndOrientation(1, data["position"], data["orientation"], physicsClientId=self.client)

    # ──────────────────────────────────────────────────────────────────────
    # Health & Status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self):
        return {"simulation_running": self._running, "healthy": True}

    def get_status(self):
        pos, _ = p.getBasePositionAndOrientation(1, physicsClientId=self.client)
        return {"current_position": pos}

# grandnexus/io/external_connector_hub.py
# ──────────────────────────────────────────────────────────────────────────
"""
ExternalConnectorHub — Universal External Integration Gateway for GrandNexus
===========================================================================

Dependencies:
    pip install fastapi uvicorn paho-mqtt requests confluent-kafka pymodbus sqlalchemy prometheus_client
"""

import logging, threading, json, time, uuid
from dataclasses import dataclass
from typing import Dict, Any
from fastapi import FastAPI
import uvicorn, requests, paho.mqtt.client as mqtt
from prometheus_client import Counter, start_http_server
from grandnexus.core.nexus_core import NexusCore

# ──────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class ConnectorConfig:
    api_port: int = 9020
    mqtt_broker: str = "localhost"
    mqtt_port: int = 1883
    prometheus_port: int = 8000

# ──────────────────────────────────────────────────────────────────────────
# 2. ExternalConnectorHub
# ──────────────────────────────────────────────────────────────────────────
class ExternalConnectorHub:
    MODULE_NAME = "external_connector_hub"

    def __init__(self, nexus: NexusCore, cfg: ConnectorConfig = ConnectorConfig()):
        self.logger = logging.getLogger("GrandNexus.ExternalConnectorHub")
        self.nexus = nexus
        self.cfg = cfg
        self._running = False
        self.app = FastAPI()

        # Prometheus metrics
        self.api_requests = Counter('api_requests_total', 'Total API Requests')
        self.mqtt_messages = Counter('mqtt_messages_total', 'Total MQTT Messages Received')

        self._configure_routes()
        self.mqtt_client = mqtt.Client()

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle methods
    # ──────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running:
            return
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["metrics_exporter"]
        )
        threading.Thread(target=self._run_api, daemon=True).start()
        threading.Thread(target=self._run_mqtt, daemon=True).start()
        start_http_server(self.cfg.prometheus_port)
        self.logger.info("ExternalConnectorHub started")

    def stop(self):
        self._running = False
        self.mqtt_client.disconnect()

    # ──────────────────────────────────────────────────────────────────────
    # API interface
    # ──────────────────────────────────────────────────────────────────────
    def _configure_routes(self):
        @self.app.post("/connectors/http/post")
        def send_http_request(payload: Dict[str, Any]):
            self.api_requests.inc()
            response = requests.post(payload["url"], json=payload["data"])
            return {"status": response.status_code, "content": response.json()}

    def _run_api(self):
        uvicorn.run(self.app, host="0.0.0.0", port=self.cfg.api_port, log_level="warning")

    # ──────────────────────────────────────────────────────────────────────
    # MQTT integration
    # ──────────────────────────────────────────────────────────────────────
    def _run_mqtt(self):
        def on_connect(client, userdata, flags, rc):
            client.subscribe("sensors/#")

        def on_message(client, userdata, msg):
            self.mqtt_messages.inc()
            payload = json.loads(msg.payload)
            self.nexus.send_message(
                source=self.MODULE_NAME,
                target="sensor_hub",
                message_type="sensor_update",
                content={"topic": msg.topic, "payload": payload}
            )

        self.mqtt_client.on_connect = on_connect
        self.mqtt_client.on_message = on_message
        self.mqtt_client.connect(self.cfg.mqtt_broker, self.cfg.mqtt_port)
        self.mqtt_client.loop_forever()

    # ──────────────────────────────────────────────────────────────────────
    # Message handling
    # ──────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]):
        if msg["type"] == "external_request":
            # Exemple de gestionnaire pour les requêtes sortantes
            url, data = msg["content"]["url"], msg["content"]["data"]
            try:
                response = requests.post(url, json=data)
                self.logger.info(f"External POST to {url} status: {response.status_code}")
            except Exception as e:
                self.logger.error(f"Error sending external request: {e}")

    # ──────────────────────────────────────────────────────────────────────
    # Health & Status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self):
        return {"api_running": self._running, "mqtt_connected": self.mqtt_client.is_connected(), "healthy": True}

    def get_status(self):
        return {"mqtt_messages_total": self.mqtt_messages._value.get()}

# grandnexus/distributed/federated_learning_coordinator.py
# ───────────────────────────────────────────────────────────────────────────
"""
FederatedLearningCoordinator — Federated Model Aggregation Service for GrandNexus
================================================================================

Dependencies :
    pip install torch numpy cryptography
"""

from __future__ import annotations
import logging, threading, time, uuid
from dataclasses import dataclass
from typing import Dict, Any, List

import torch
import numpy as np
from cryptography.fernet import Fernet  # For lightweight encryption of updates

from grandnexus.core.nexus_core import NexusCore

# ───────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ───────────────────────────────────────────────────────────────────────────
@dataclass
class FedConfig:
    aggregation_interval: float = 600.0   # secondes entre agrégations
    tick_channel: str = "slow"
    encryption_key: bytes = Fernet.generate_key()  # clé symétrique pour chiffrer mises à jour


# ───────────────────────────────────────────────────────────────────────────
# 2. FederatedLearningCoordinator
# ───────────────────────────────────────────────────────────────────────────
class FederatedLearningCoordinator:
    MODULE_NAME = "federated_learning_coordinator"
    MSG_LOCAL_UPDATE = "local_model_update"     # attend : {"client_id", "update_encrypted"}
    MSG_GLOBAL_UPDATE = "global_model_update"   # envoie : {"round_id", "state_dict"}

    def __init__(self, nexus: NexusCore, cfg: FedConfig = FedConfig()):
        self.logger = logging.getLogger("GrandNexus.FedLearn")
        self.nexus = nexus
        self.cfg = cfg
        self._lock = threading.RLock()
        self._running = False

        # Registre des mises à jour reçues par round
        self._pending_updates: Dict[str, List[Dict[str, Any]]] = {}
        self._round = 0
        self._fernet = Fernet(self.cfg.encryption_key)

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ──────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running: return
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=["cognitive_clock", "multi_agent_coordinator"],
        )
        clk = self.nexus.get_module("cognitive_clock")
        if clk:
            clk.subscribe(self.cfg.tick_channel, self._on_tick)
        self.logger.info("FederatedLearningCoordinator started")

    def stop(self):
        self._running = False

    # ──────────────────────────────────────────────────────────────────────
    # Message handling — réception des updates chiffrés
    # ──────────────────────────────────────────────────────────────────────
    def handle_message(self, msg: Dict[str, Any]):
        if msg.get("type") == self.MSG_LOCAL_UPDATE:
            content = msg["content"]
            round_id = content["round_id"]
            encrypted = content["update_encrypted"].encode()
            try:
                raw = self._fernet.decrypt(encrypted)
                state_dict_np = torch.load(torch.io.BytesIO(raw), map_location="cpu")
                with self._lock:
                    self._pending_updates.setdefault(round_id, []).append(state_dict_np)
                self.logger.debug(f"Received local update from {content['client_id']} for round {round_id}")
            except Exception as e:
                self.logger.error(f"Failed to decrypt or deserialize update: {e}")

    # ──────────────────────────────────────────────────────────────────────
    # Tick callback — agrégation périodique
    # ──────────────────────────────────────────────────────────────────────
    def _on_tick(self, _):
        now = time.time()
        # Lancer une agrégation à chaque intervalle
        if not hasattr(self, "_last_agg"): self._last_agg = now
        if now - self._last_agg < self.cfg.aggregation_interval:
            return
        self._aggregate_round()
        self._last_agg = now

    # ──────────────────────────────────────────────────────────────────────
    # Agrégation fédérée (FedAvg)
    # ──────────────────────────────────────────────────────────────────────
    def _aggregate_round(self):
        with self._lock:
            r = f"round_{self._round}"
            updates = self._pending_updates.pop(r, [])
        if not updates:
            self.logger.info(f"No updates to aggregate for {r}")
            self._round += 1
            return

        # FedAvg : moyenne pondérée uniforme
        avg_state = {}
        for key in updates[0].keys():
            stacked = torch.stack([u[key] for u in updates], dim=0)
            avg_state[key] = torch.mean(stacked, dim=0)

        # Préparer la diffusion du modèle global
        payload = {
            "round_id": r,
            "state_dict": avg_state
        }
        # Diffuser via MultiAgentCoordinator
        mac = self.nexus.get_module("multi_agent_coordinator")
        if mac:
            mac.broadcast({"topic":"model_update","data":payload})
        # Mettre à jour localement le WorldModelLearner
        wml = self.nexus.get_module("world_model_learner")
        if wml and hasattr(wml.model, "load_state_dict"):
            wml.model.load_state_dict(avg_state)
            self.logger.info(f"Applied aggregated model for {r} locally")

        # Notifier les participants (via NexusCore message)
        self.nexus.send_message(
            source=self.MODULE_NAME,
            target="all",  # convention pour diffusion globale
            message_type=self.MSG_GLOBAL_UPDATE,
            content=payload,
            priority=5
        )
        self.logger.info(f"FedAvg aggregation completed for {r} with {len(updates)} updates")
        self._round += 1

    # ──────────────────────────────────────────────────────────────────────
    # Méthodes utilitaires pour clients — appelées par WorldModelLearner ou ContinuousLearner
    # ──────────────────────────────────────────────────────────────────────
    def submit_local_update(self, client_id: str, state_dict: Dict[str, torch.Tensor]):
        """
        Sérialiser et chiffrer state_dict, puis envoyer à l'orchestrateur.
        """
        buf = torch.io.BytesIO()
        torch.save(state_dict, buf)
        raw = buf.getvalue()
        encrypted = self._fernet.encrypt(raw).decode()
        payload = {
            "round_id": f"round_{self._round}",
            "client_id": client_id,
            "update_encrypted": encrypted
        }
        self.nexus.send_message(
            source=self.MODULE_NAME,
            target=self.MODULE_NAME,
            message_type=self.MSG_LOCAL_UPDATE,
            content=payload
        )

    # ──────────────────────────────────────────────────────────────────────
    # Health & status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self):
        with self._lock:
            pending = len(self._pending_updates.get(f"round_{self._round}", []))
        return {"current_round": self._round, "pending_updates": pending, "healthy": True}

    def get_status(self):
        return {"round": self._round, "pending": len(self._pending_updates.get(f"round_{self._round}", []))}

# grandnexus/ops/devsecops_orchestrator.py
# ──────────────────────────────────────────────────────────────────────────
"""
DevSecOpsOrchestrator — CI/CD & Security Automation for GrandNexus
==================================================================

Fonctions :
  • Surveillance Git (webhook ou polling)
  • Tests unitaires, linting, coverage
  • Analyse SAST (Bandit), DAST (OWASP ZAP)
  • Build & scan d’image Docker (Trivy)
  • Push image vers registry (DockerHub/ECR/GCR)
  • Déploiement automatisé sur Kubernetes (kubectl / Helm)
  • Notifications (Slack, email) et métriques Prometheus
  • Gestion des secrets via Vault or K8s Secrets

Dépendances externes :
    pip install gitpython docker pytest bandit trivy python-kubeconfig prometheus-client slack_sdk
"""
import logging, threading, time, uuid, os, subprocess, tempfile
from dataclasses import dataclass
from typing import Optional, Dict, Any
from prometheus_client import Counter, Gauge, start_http_server
from slack_sdk import WebClient
from git import Repo
from grandnexus.core.nexus_core import NexusCore

# ──────────────────────────────────────────────────────────────────────────
# 1. Configuration
# ──────────────────────────────────────────────────────────────────────────
@dataclass
class DevSecOpsConfig:
    git_repo_url: str
    git_branch: str = "main"
    poll_interval: float = 60.0                # s
    docker_registry: str = "registry.example.com/grandnexus"
    kubernetes_context: str = "prod-cluster"
    helm_chart_path: str = "./deploy/helm/grandnexus"
    slack_token: Optional[str] = None
    slack_channel: str = "#deployments"
    prometheus_port: int = 9100

# ──────────────────────────────────────────────────────────────────────────
# 2. DevSecOpsOrchestrator
# ──────────────────────────────────────────────────────────────────────────
class DevSecOpsOrchestrator:
    MODULE_NAME = "devsecops_orchestrator"

    def __init__(self, nexus: NexusCore, cfg: DevSecOpsConfig):
        self.logger = logging.getLogger("GrandNexus.DevSecOps")
        self.nexus = nexus
        self.cfg = cfg
        self._running = False
        self._last_commit = None
        self._lock = threading.RLock()

        # Metrics
        self.c_runs = Counter("devsecops_runs_total", "Total pipeline runs")
        self.c_failures = Counter("devsecops_failures_total", "Failed pipeline runs")
        self.g_last_duration = Gauge("devsecops_last_duration_seconds", "Last run duration")

        # Slack client
        self.slack = WebClient(token=self.cfg.slack_token) if self.cfg.slack_token else None

        # Start Prometheus endpoint
        start_http_server(self.cfg.prometheus_port)

    # ──────────────────────────────────────────────────────────────────────
    # Lifecycle
    # ──────────────────────────────────────────────────────────────────────
    def start(self):
        if self._running: return
        self._running = True
        self.nexus.register_module(
            name=self.MODULE_NAME,
            module=self,
            dependencies=[],
        )
        threading.Thread(target=self._poll_loop, daemon=True).start()
        self.logger.info("DevSecOpsOrchestrator started")

    def stop(self):
        self._running = False

    # ──────────────────────────────────────────────────────────────────────
    # Polling Git & triggering pipeline
    # ──────────────────────────────────────────────────────────────────────
    def _poll_loop(self):
        repo_dir = tempfile.mkdtemp(prefix="gnx_repo_")
        repo = Repo.clone_from(self.cfg.git_repo_url, repo_dir, branch=self.cfg.git_branch)
        while self._running:
            repo.remotes.origin.fetch()
            head = repo.head.commit.hexsha
            if head != self._last_commit:
                self._last_commit = head
                self.logger.info(f"New commit detected: {head}")
                threading.Thread(target=self._run_pipeline, args=(repo_dir, head), daemon=True).start()
            time.sleep(self.cfg.poll_interval)

    # ──────────────────────────────────────────────────────────────────────
    # Pipeline steps
    # ──────────────────────────────────────────────────────────────────────
    def _run_pipeline(self, repo_dir: str, commit: str):
        start = time.time()
        self.c_runs.inc()
        success = True
        try:
            # 1. Checkout
            self._shell(f"git -C {repo_dir} checkout {commit}")

            # 2. Unit tests & coverage
            self._shell(f"pytest {repo_dir}/src --maxfail=1 --disable-warnings")

            # 3. Static analysis (Bandit)
            self._shell(f"bandit -r {repo_dir}/src -lll")

            # 4. Build Docker image
            image_tag = f"{self.cfg.docker_registry}:{commit}"
            self._shell(f"docker build -t {image_tag} {repo_dir}")

            # 5. Scan image (Trivy)
            self._shell(f"trivy image --exit-code 1 --severity HIGH,CRITICAL {image_tag}")

            # 6. Push image
            self._shell(f"docker push {image_tag}")

            # 7. Deploy via Helm
            self._shell(
                f"helm upgrade --install grandnexus {self.cfg.helm_chart_path} "
                f"--kube-context {self.cfg.kubernetes_context} "
                f"--set image.repository={self.cfg.docker_registry} --set image.tag={commit}"
            )

            # 8. Post-deploy smoke tests
            self._shell(f"pytest {repo_dir}/tests/smoke.py")

            self._notify_slack(f"✅ Deployment successful for commit `{commit}`")
        except Exception as e:
            success = False
            self.c_failures.inc()
            self.logger.error(f"Pipeline failed at commit {commit}: {e}", exc_info=True)
            self._notify_slack(f"❌ Deployment failed for commit `{commit}`: {e}")
        finally:
            duration = time.time() - start
            self.g_last_duration.set(duration)
            self.logger.info(f"Pipeline duration: {duration:.1f}s")

    # ──────────────────────────────────────────────────────────────────────
    # Helpers
    # ──────────────────────────────────────────────────────────────────────
    def _shell(self, cmd: str):
        self.logger.debug(f"Running shell: {cmd}")
        res = subprocess.run(cmd, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        self.logger.debug(res.stdout.decode())

    def _notify_slack(self, message: str):
        if self.slack:
            try:
                self.slack.chat_postMessage(channel=self.cfg.slack_channel, text=message)
            except Exception as e:
                self.logger.warning(f"Slack notification failed: {e}")

    # ──────────────────────────────────────────────────────────────────────
    # Health & Status
    # ──────────────────────────────────────────────────────────────────────
    def health_check(self) -> Dict[str, Any]:
        return {"last_commit": self._last_commit or "", "healthy": True}

    def get_status(self) -> Dict[str, Any]:
        return {"last_commit": self._last_commit, "runs": int(self.c_runs._value.get()), "failures": int(self.c_failures._value.get())}

